(window.MAP_DATA = window.MAP_DATA || {})["language_6"] = {"grade":6,"subject":"language","units":[{"id":"U1","title":"Argument and Explanation: Claims, Evidence, Counterclaims and Structure","goal":"WR","band":"181–220","skills":["Introduce a claim and organize reasons and evidence clearly","Acknowledge an opposing claim and respond to it","Organize information by comparison, contrast, or cause and effect","Use transitions, a formal style and a strong conclusion"],"vocab":[["claim","the position a writer argues for in an argument"],["counterclaim","an opposing view that disagrees with the writer’s claim"],["rebuttal","the writer’s answer that shows why the counterclaim is weaker"],["credible source","a source that is trustworthy because experts wrote or checked it"],["compare-and-contrast structure","a way of organizing that shows how two things are alike and different"],["formal style","serious, clear language without slang, used for school and work writing"]],"sets":[{"set":"A","passage":{"title":"Plastic Bottles Should Go","genre":"draft","paras":["(1) Every day, students at our school throw away hundreds of plastic water bottles. (2) The school should stop selling single-use plastic bottles in the cafeteria. (3) Most of these bottles are never recycled. (4) Instead, they end up in landfills or in the ocean, where they can take hundreds of years to break down. (5) Some students say that bottled water is more convenient. (6) The cafeteria also sells sandwiches and fruit. (7) Refill stations would make it just as easy to get clean water, and reusable bottles would save families money."],"intro":"Yousef is writing an argument essay for the school newspaper. Read his draft and answer the questions."},"items":[{"n":1,"t":"mc","s":"Which sentence states Yousef’s claim?","o":["sentence 1","sentence 2","sentence 3","sentence 5"],"k":"B","sk":"States a clear claim or thesis","b":"181–190","g":"WR"},{"n":2,"t":"mc","s":"Which sentence does NOT support the claim and should be removed?","o":["sentence 3","sentence 4","sentence 6","sentence 7"],"k":"C","sk":"Identifies a sentence that does not belong","b":"181–190","g":"WR"},{"n":3,"t":"mc","s":"Which transition would BEST begin sentence 7 to respond to the opposing view in sentence 5?","o":["Similarly,","As a result,","For example,","However,"],"k":"D","sk":"Acknowledges and answers an opposing claim","b":"191–200","g":"WR"},{"n":4,"t":"mc","s":"Which piece of evidence would BEST support sentence 3?","o":["A national study found that fewer than one in three plastic bottles is recycled.","Many students prefer cold water to warm water after a long recess outside.","Plastic bottles come in many sizes, colors and shapes in most large stores today.","Our cafeteria is open from eight o’clock in the morning until two o’clock."],"k":"A","sk":"Chooses relevant evidence to support a point","b":"201–210","g":"WR"},{"n":5,"t":"mc","s":"Which source would be the MOST credible for evidence about plastic in the ocean?","o":["a comment posted under a video about plastic art","a report from a university marine science department","a blog post by a student who visited the beach once","an advertisement for a company that sells reusable bottles"],"k":"B","sk":"Chooses a useful source or research question","b":"201–210","g":"WR"},{"n":6,"t":"mc","s":"Which sentence would be the BEST conclusion for the essay?","o":["Many students drink a lot of water during the day, especially after sports and physical education classes.","Some people think that plastic bottles are useful, and some other people think that they are not.","By replacing plastic bottles with refill stations, our school can protect the environment and save money.","Plastic was invented more than one hundred years ago by scientists who worked in laboratories."],"k":"C","sk":"Chooses an effective concluding sentence","b":"211–220","g":"WR"}]},{"set":"B","passage":{"title":"Two Kinds of Camels","genre":"draft","paras":["(1) There are two main kinds of camels: the dromedary and the Bactrian camel. (2) The dromedary has one hump, while the Bactrian camel has two. (3) Dromedaries live mainly in the hot deserts of the Middle East and North Africa. (4) Bactrian camels, on the other hand, live in the cold, rocky deserts of Central Asia. (5) Both kinds store fat in their humps. (6) This fat gives them energy when food is scarce. (7) Bactrian camels grow a thick, shaggy coat in winter to stay warm."],"intro":"Reem is writing an informative report that compares two kinds of camels. Read her draft and answer the questions."},"items":[{"n":1,"t":"mc","s":"Which phrase in sentence 4 signals a contrast?","o":["the cold, rocky deserts","of Central Asia","Bactrian camels","on the other hand"],"k":"D","sk":"Chooses a transition that connects ideas","b":"181–190","g":"WR"},{"n":2,"t":"mc","s":"How does Reem mainly organize her report?","o":["by comparing and contrasting two kinds of camels","by telling events in the order that they happened","by describing a problem and then offering a solution","by explaining the steps for caring for a pet camel"],"k":"A","sk":"Puts sentences or events in a logical order","b":"191–200","g":"WR"},{"n":3,"t":"mc","s":"Reem wants to add a heading before sentence 5. Which heading fits BEST?","o":["The History of Camel Racing","Where Camels Live Today","How the Two Camels Are Alike","How to Ride a Camel Safely"],"k":"C","sk":"Chooses a topic sentence that introduces the main idea","b":"191–200","g":"WR"},{"n":4,"t":"mc","s":"Which transition BEST begins sentence 5?","o":["Because of these differences,","In spite of these differences,","In place of these differences,","Instead of these differences,"],"k":"B","sk":"Chooses a transition that connects ideas","b":"201–210","g":"WR"},{"n":5,"t":"mc","s":"Which sentence would BEST follow sentence 6 to add a relevant detail?","o":["Some zoos keep camels together with horses, goats and donkeys.","When a camel uses up this fat, its hump can shrink and droop.","Camels are often seen at festivals, races and markets in many towns.","Many children enjoy riding camels at festivals and on farm visits."],"k":"B","sk":"Adds a detail that supports the main idea","b":"201–210","g":"WR"},{"n":6,"t":"mc","s":"Which sentence would make the BEST introduction to Reem’s report?","o":["This report is going to be about camels and all of the many different things about them.","Camels are animals, and there are many kinds of animals living all over the world today.","Few animals are as well suited to harsh deserts as the camel, but not all camels are alike.","I have always liked camels a lot, so I decided that I would write about them in this report."],"k":"C","sk":"Chooses an effective introduction","b":"211–220","g":"WR"},{"n":7,"t":"mc","s":"Reem found the fact in sentence 7 in a book. Which information is MOST important to include when she lists this book as a source?","o":["the author, title, publisher and year the book was published","the name of the library and the shelf where she found the book","the price of the book and the store where it can be bought","the number of pages and the color of the cover of the book"],"k":"A","sk":"Paraphrases or cites a source correctly","b":"211–220","g":"WR"}]}]},{"id":"U2","title":"Narrative Craft, Research and Precise Language","goal":"WR","band":"181–220","skills":["Use dialogue, pacing and description to develop events and characters","Use precise words and sensory language","Gather relevant information and paraphrase without plagiarizing","Remove informal or wordy language and keep a consistent tone"],"vocab":[["pacing","how quickly or slowly a writer moves through events in a story"],["sensory language","words that help the reader see, hear, smell, taste or feel something"],["dialogue","the words characters say to each other, shown in quotation marks"],["paraphrase","to restate a source’s ideas in your own words and sentence structure"],["plagiarism","using someone else’s words or ideas without giving them credit"],["domain-specific vocabulary","words that belong to a subject, such as erosion in science"]],"sets":[{"set":"A","passage":{"title":"The Power Outage","genre":"draft","paras":["(1) The lights flickered twice and then went out. (2) The whole apartment was dark. (3) My little sister grabbed my arm. (4) “I can’t see anything,” she said. (5) I felt my way to the kitchen drawer and found a flashlight. (6) We sat by the window and watched the dark city. (7) Then, one by one, the stars appeared above the rooftops."],"intro":"Bader is writing a story about a night when the power went out. Read his draft and answer the questions."},"items":[{"n":1,"t":"mc","s":"Which word could replace “said” in sentence 4 to BEST show that the sister is scared?","o":["explained","laughed","announced","whispered"],"k":"D","sk":"Chooses precise or vivid language","b":"181–190","g":"WR"},{"n":2,"t":"mc","s":"Which transition could BEST replace “Then” in sentence 7 to show that time has passed?","o":["In contrast,","For example,","After a while,","Therefore,"],"k":"C","sk":"Chooses a transition that connects ideas","b":"181–190","g":"WR"},{"n":3,"t":"mc","s":"Which revision of sentence 2 uses the MOST vivid sensory language?","o":["The apartment was very, very dark, and it was not light anywhere at all.","Darkness swallowed the apartment, and the hum of the refrigerator stopped.","It was dark in the whole apartment, and that was just how it was that night.","The apartment was dark because the power was not working at that time."],"k":"B","sk":"Chooses precise or vivid language","b":"191–200","g":"WR"},{"n":4,"t":"mc","s":"Which sentence could be added after sentence 3 to show the sister’s feelings through her actions?","o":["Her hand was trembling, and her breathing was quick.","Power outages can happen during big summer storms.","Our apartment is on the fourth floor of the building.","My sister is seven years old and in the second grade."],"k":"A","sk":"Uses narrative techniques: dialogue, description and pacing","b":"191–200","g":"WR"},{"n":5,"t":"mc","s":"Which sentence would be the BEST ending for the story?","o":["Power outages are usually fixed within a few hours by workers from the company.","Our city has more than two million people living in many tall apartment buildings.","The flashlight needed new batteries, so we put it back in the kitchen drawer.","For the first time, I realized how bright the sky could be when the city was dark."],"k":"D","sk":"Chooses an effective concluding sentence","b":"201–210","g":"WR"},{"n":6,"t":"mc","s":"Bader wants to slow down the moment in sentence 5 to build suspense. Which revision does this BEST?","o":["I got the flashlight out of the kitchen drawer, which is where we always keep it at home.","I quickly found a flashlight in the kitchen drawer and then came right back to the window.","I slid my hand along the counter, past the cold sink, until my fingers touched the drawer.","I went to the kitchen, and I got the flashlight that was in the drawer near the sink there."],"k":"C","sk":"Uses narrative techniques: dialogue, description and pacing","b":"211–220","g":"WR"}]},{"set":"B","passage":{"title":"Research Notes: The Empty Quarter","genre":"draft","paras":["**Source:** “The Rub’ al Khali, or Empty Quarter, covers about 650,000 square kilometers of the Arabian Peninsula. It is one of the largest sand deserts in the world. Some of its dunes rise more than 250 meters high. Despite the harsh conditions, animals such as the Arabian oryx, sand cats and desert foxes live there.”","**Draft**","(1) The Empty Quarter is a giant desert. (2) It covers about 650,000 square kilometers. (3) Its dunes are really, really big. (4) Even though it is very hot and dry, some animals still survive there. (5) People have crossed the desert by camel for centuries. (6) In 1931, a British explorer named Bertram Thomas became the first known European to cross it."],"intro":"Fahad is writing a report about the Rub’ al Khali. Read the source and his draft, then answer the questions."},"items":[{"n":1,"t":"mc","s":"Which sentence in the draft is too informal for a report?","o":["sentence 2","sentence 3","sentence 5","sentence 6"],"k":"B","sk":"Keeps a consistent formal style and objective tone","b":"191–200","g":"WR"},{"n":2,"t":"mc","s":"Which revision of sentence 3 uses information from the source accurately and in Fahad’s own words?","o":["Its dunes are big, and some are even bigger than others.","Its dunes are the tallest dunes anywhere on Earth today.","Some of its dunes rise more than 650,000 meters high.","Some of its sand dunes are taller than 250 meters."],"k":"D","sk":"Uses notes and facts accurately in writing","b":"201–210","g":"WR"},{"n":3,"t":"mc","s":"Which phrase should replace “a giant desert” in sentence 1 to use more precise language?","o":["one of the world’s largest sand deserts","the only sand desert in all of Asia","a really giant and enormous sandy place","a desert that is very giant and big"],"k":"A","sk":"Chooses precise or vivid language","b":"201–210","g":"WR"},{"n":4,"t":"mc","s":"Fahad wants to learn how animals survive in the Empty Quarter. Which search would be MOST useful?","o":["list of the biggest deserts and oceans in the whole world","how to build a tall sand castle at the beach","Arabian oryx sand cat desert survival adaptations","Bertram Thomas birthday, family and his favorite foods"],"k":"C","sk":"Chooses a useful source or research question","b":"201–210","g":"WR"},{"n":5,"t":"mc","s":"Which revision of sentence 4 adds the MOST specific details from the source?","o":["Even though it is very hot and dry, some animals and plants live there.","Even though it is hot, many people live there in large modern cities.","Even though it is very hot and dry, some animals still survive there today.","Even so, animals such as the Arabian oryx and the sand cat survive there."],"k":"D","sk":"Uses notes and facts accurately in writing","b":"211–220","g":"WR"},{"n":6,"t":"mc","s":"Which sentence includes information that does NOT come from the source, so Fahad must credit another source for it?","o":["sentence 1","sentence 2","sentence 4","sentence 6"],"k":"D","sk":"Paraphrases or cites a source correctly","b":"211–220","g":"WR"},{"n":7,"t":"mc","s":"Which sentence would be the BEST conclusion for the report?","o":["Sand is made of tiny grains of rock and minerals that the wind can carry very far.","Many explorers have traveled across deserts, oceans and mountains around the world.","Although it seems empty, the Rub’ al Khali is full of surprising life and history.","The Empty Quarter is located in the southern part of the very large Arabian Peninsula."],"k":"C","sk":"Chooses an effective concluding sentence","b":"211–220","g":"WR"}]}]},{"id":"U3","title":"Pronouns: Case, Intensive Pronouns, Shifts and Clear References","goal":"GU","band":"181–220","skills":["Use subjective, objective and possessive pronouns correctly","Use intensive pronouns such as myself and ourselves","Recognize and correct shifts in pronoun number and person","Recognize and correct vague pronouns"],"vocab":[["subjective case","pronouns used as subjects: I, he, she, we, they"],["objective case","pronouns used as objects: me, him, her, us, them"],["possessive case","pronouns that show ownership: my, mine, their, theirs"],["intensive pronoun","a pronoun ending in -self or -selves that adds emphasis: the principal herself"],["pronoun shift","an incorrect change in number or person, such as from students to you"],["vague pronoun","a pronoun that could refer to more than one noun"]],"sets":[{"set":"A","passage":null,"items":[{"n":1,"t":"mc","s":"Which pronoun correctly completes the sentence?\n“My cousin and ___ built a model volcano.”","o":["myself","I","mine","me"],"k":"B","sk":"Uses the correct pronoun case","b":"181–190","g":"GU"},{"n":2,"t":"mc","s":"Which pronoun correctly completes the sentence?\n“The coach gave the trophy to Lama and ___.”","o":["me","I","myself","mine"],"k":"A","sk":"Uses the correct pronoun case","b":"191–200","g":"GU"},{"n":3,"t":"mc","s":"Which word correctly completes the sentence?\n“The members of the band tuned ___ instruments.”","o":["his","its","her","their"],"k":"D","sk":"Makes pronouns agree with their antecedents","b":"191–200","g":"GU"},{"n":4,"t":"mc","s":"Which sentence uses an intensive pronoun correctly?","o":["Herself, the principal handed out the awards.","The principal and herself handed out the awards.","The principal herself handed out the awards.","The principal handed out the awards to herself and we."],"k":"C","sk":"Uses reflexive and intensive pronouns","b":"191–200","g":"GU"},{"n":5,"t":"mc","s":"Which sentence has an incorrect shift in pronoun person?","o":["When students study hard, they get better grades.","When you study hard, you get better grades.","When we study hard, we get better grades.","When students study hard, you get better grades."],"k":"D","sk":"Makes pronouns agree with their antecedents","b":"201–210","g":"GU"},{"n":6,"t":"mc","s":"Which sentence has a vague pronoun?","o":["Nora told Hessa, “You have won the contest.”","Nora told Hessa that Hessa had won the contest.","Nora told Hessa that she had won the contest.","Nora won the contest, and she told Hessa about it."],"k":"C","sk":"Corrects vague or unclear pronouns","b":"211–220","g":"GU"}]},{"set":"B","passage":{"title":"The Soccer Tournament","genre":"draft","paras":["(1) Last month, my teammates and me played in the city soccer tournament. (2) Our coach told us that we should be proud of ourself no matter what happened. (3) In the first game, Khalid passed the ball to Omar, and he scored. (4) Between you and I, the second game was the hardest. (5) If a player is tired, you should ask the coach for a break. (6) In the final, our goalkeeper himself blocked three shots. (7) The other team shook hands with us, and they said we had played well."],"intro":"Majed wrote about his team’s tournament. His draft has some pronoun mistakes. Read it and answer the questions."},"items":[{"n":1,"t":"mc","s":"What is the correct way to write sentence 1?","o":["Last month, me and my teammates played in the city soccer tournament.","Last month, myself and my teammates played in the city soccer tournament.","Last month, my teammates and I played in the city soccer tournament.","Last month, my teammates and myself played in the city soccer tournament."],"k":"C","sk":"Uses the correct pronoun case","b":"181–190","g":"GU"},{"n":2,"t":"mc","s":"Which pronoun correctly completes the sentence?\n“The trophy now sits in the school hall, where everyone can see ___.”","o":["them","its","they","it"],"k":"D","sk":"Uses pronouns correctly","b":"181–190","g":"GU"},{"n":3,"t":"mc","s":"Which word should replace “ourself” in sentence 2?","o":["ourselves","ourselfs","themselves","us"],"k":"A","sk":"Uses reflexive and intensive pronouns","b":"191–200","g":"GU"},{"n":4,"t":"mc","s":"In sentence 3, the pronoun “he” is unclear. Which revision is clearest?","o":["In the first game, he passed the ball to him, and Omar scored.","In the first game, Khalid passed the ball to Omar, and Omar scored.","In the first game, Khalid passed the ball to Omar, and then he scored.","In the first game, Khalid passed it to Omar, and he scored a goal."],"k":"B","sk":"Corrects vague or unclear pronouns","b":"201–210","g":"GU"},{"n":5,"t":"mc","s":"What is the correct way to begin sentence 4?","o":["Between I and you,","Between you and I,","Between you and me,","Between yourself and I,"],"k":"C","sk":"Uses the correct pronoun case","b":"201–210","g":"GU"},{"n":6,"t":"mc","s":"What is the correct way to write sentence 5?","o":["If a player is tired, him should ask the coach for a break.","If a player is tired, he should ask the coach for a break.","If a player is tired, we should ask the coach for a break.","If a player is tired, you should ask the coach for a break."],"k":"B","sk":"Makes pronouns agree with their antecedents","b":"201–210","g":"GU"},{"n":7,"t":"mc","s":"What is the purpose of the word “himself” in sentence 6?","o":["to show that the goalkeeper was alone","to replace the word “goalkeeper”","to show that the action happened in the past","to emphasize the goalkeeper"],"k":"D","sk":"Uses reflexive and intensive pronouns","b":"211–220","g":"GU"}]}]},{"id":"U4","title":"Sentence Variety, Agreement and Standard Usage","goal":"GU","band":"181–220","skills":["Vary sentence patterns: simple, compound and complex","Fix fragments, run-ons and comma splices","Make subjects and verbs agree, even with phrases between them","Choose between frequently confused words such as affect/effect and than/then"],"vocab":[["simple sentence","a sentence with one independent clause"],["compound sentence","two independent clauses joined by a comma and a conjunction or by a semicolon"],["complex sentence","an independent clause joined with at least one dependent clause"],["comma splice","two complete sentences joined with only a comma"],["dependent clause","a clause that cannot stand alone, often starting with because, although or when"],["standard English","the form of English expected in formal writing and speaking"]],"sets":[{"set":"A","passage":null,"items":[{"n":1,"t":"mc","s":"Which sentence is written correctly?","o":["My brother is taller then I am.","My brother is more taller than me.","My brother is tallest than I am.","My brother is taller than I am."],"k":"D","sk":"Chooses between frequently confused words","b":"181–190","g":"GU"},{"n":2,"t":"mc","s":"Which word correctly completes the sentence?\n“The loud music did not ___ his concentration.”","o":["affect","effected","affects","effect"],"k":"A","sk":"Chooses between frequently confused words","b":"191–200","g":"GU"},{"n":3,"t":"mc","s":"Which word correctly completes the sentence?\n“The box of old photographs ___ in the attic.”","o":["are","were","is","have been"],"k":"C","sk":"Makes subjects and verbs agree","b":"191–200","g":"GU"},{"n":4,"t":"mc","s":"Which of these is a comma splice?","o":["We went to the park because the museum was closed.","The museum was closed, we went to the park instead.","The museum was closed, so we went to the park instead.","Because the museum was closed, we went to the park."],"k":"B","sk":"Recognizes complete sentences, fragments and run-ons","b":"191–200","g":"GU"},{"n":5,"t":"mc","s":"Which sentence is a complex sentence?","o":["It rained, and the game went on anyway.","It was raining hard, but the long game continued.","Although it was raining, the game continued.","The game continued in the heavy rain."],"k":"C","sk":"Forms simple, compound and complex sentences","b":"201–210","g":"GU"},{"n":6,"t":"mc","s":"Which sentence uses standard English?","o":["We should of went to the beach.","We could have gone to the beach.","We could have went to the beach.","We could of gone to the beach."],"k":"B","sk":"Chooses between frequently confused words","b":"211–220","g":"GU"}]},{"set":"B","passage":{"title":"The Book Fair","genre":"draft","paras":["(1) Every spring, our school holds a book fair in the library. (2) This year, the selection of books were larger than ever. (3) Students could choose from mysteries, biographies and science books. (4) Because the fair was so popular. (5) Many students bought more books then they had planned. (6) The money from the fair will be used to buy new computers, the library needs them. (7) Next year, the fair will last a whole week."],"intro":"Shahad wrote a report about the school book fair. Her draft has some mistakes. Read it and answer the questions."},"items":[{"n":1,"t":"mc","s":"Which word should replace “then” in sentence 5?","o":["thin","them","that","than"],"k":"D","sk":"Chooses between frequently confused words","b":"181–190","g":"GU"},{"n":2,"t":"mc","s":"Sentence 4 is a fragment. Which is the BEST way to fix it?","o":["Because the fair was so popular, it stayed open an extra day.","Because the fair, which was so popular with all the students.","Because the fair was so very popular, and it stayed open all day.","Because the fair was so popular with the students and teachers."],"k":"A","sk":"Recognizes complete sentences, fragments and run-ons","b":"191–200","g":"GU"},{"n":3,"t":"mc","s":"Which word should replace “were” in sentence 2?","o":["have been","was","being","are"],"k":"B","sk":"Makes subjects and verbs agree","b":"201–210","g":"GU"},{"n":4,"t":"mc","s":"Which word correctly completes the sentence?\n“The book fair had a positive ___ on students’ reading habits.”","o":["affected","effects","effect","affect"],"k":"C","sk":"Chooses between frequently confused words","b":"201–210","g":"GU"},{"n":5,"t":"mc","s":"What is the BEST way to fix the comma splice in sentence 6?","o":["The money, from the fair will be used to buy new computers, the library needs them.","The money from the fair will be used to buy new computers, which the library needs.","The money from the fair will be used, to buy new computers, the library needs them.","The money from the fair will be used to buy new computers the library needs them."],"k":"B","sk":"Recognizes complete sentences, fragments and run-ons","b":"211–220","g":"GU"},{"n":6,"t":"mc","s":"Which revision of sentence 7 creates a complex sentence?","o":["If the fair raises enough money, it will last a whole week next year.","Next year, the whole fair will last for a whole week in the library.","Next year, the fair will last for a whole week with many more books.","Next year, the fair will last a whole week, and it will be even more fun."],"k":"A","sk":"Forms simple, compound and complex sentences","b":"211–220","g":"GU"},{"n":7,"t":"mc","s":"Which word correctly completes the sentence?\n“Neither the posters nor the sign ___ ready for the fair.”","o":["were","have been","was","are"],"k":"C","sk":"Uses correlative conjunctions","b":"211–220","g":"GU"}]}]},{"id":"U5","title":"Commas, Parentheses and Dashes for Extra Information","goal":"ME","band":"181–220","skills":["Use commas, parentheses or dashes to set off nonrestrictive and parenthetical elements","Use commas after introductory elements and before conjunctions","Use commas between coordinate adjectives","Avoid unnecessary commas"],"vocab":[["nonrestrictive element","extra information that can be removed without changing the main meaning"],["parenthetical element","an aside or interruption, such as in fact or by the way"],["appositive","a noun phrase that renames a noun: my aunt, a doctor,"],["parentheses","the marks ( ) that set off less important extra information"],["dash","the mark — that sets off extra information with strong emphasis"],["coordinate adjectives","adjectives that describe a noun equally: a long, hot day"]],"sets":[{"set":"A","passage":null,"items":[{"n":1,"t":"mc","s":"Which sentence uses commas correctly to set off extra information?","o":["My aunt, a doctor, works at the hospital.","My aunt, a doctor works at the hospital.","My, aunt a doctor works at the hospital.","My aunt a doctor, works at the hospital."],"k":"A","sk":"Uses commas, parentheses or dashes to set off extra information","b":"181–190","g":"ME"},{"n":2,"t":"mc","s":"Which sentence uses a comma correctly?","o":["In, fact the test was easier than we expected.","In fact the test, was easier than we expected.","In fact the test was easier, than we expected.","In fact, the test was easier than we expected."],"k":"D","sk":"Uses a comma after an introductory word, phrase or clause","b":"181–190","g":"ME"},{"n":3,"t":"mc","s":"Which sentence uses commas correctly?","o":["It was a long exhausting, day.","It was a, long exhausting day.","It was a long, exhausting day.","It was, a long exhausting day."],"k":"C","sk":"Uses commas between coordinate adjectives","b":"191–200","g":"ME"},{"n":4,"t":"mc","s":"Which sentence uses parentheses correctly?","o":["The Red Sea which (borders Saudi Arabia) is famous for its coral.","The Red Sea (which borders Saudi Arabia) is famous for its coral.","The Red Sea (which borders Saudi Arabia is famous) for its coral.","(The Red Sea) which borders Saudi Arabia is famous for its coral."],"k":"B","sk":"Uses commas, parentheses or dashes to set off extra information","b":"191–200","g":"ME"},{"n":5,"t":"mc","s":"Which sentence uses dashes correctly?","o":["The answer—believe it or not was hidden—in the first clue.","The answer believe—it or not—was hidden in the first clue.","The—answer believe it or not—was hidden in the first clue.","The answer—believe it or not—was hidden in the first clue."],"k":"D","sk":"Uses commas, parentheses or dashes to set off extra information","b":"201–210","g":"ME"},{"n":6,"t":"mc","s":"Which sentence is punctuated correctly?","o":["Students, who arrive late must sign in at the office.","Students who arrive late must sign in at the office.","Students, who arrive late, must sign in at the office.","Students who arrive late, must sign in at the office."],"k":"B","sk":"Uses commas, parentheses or dashes to set off extra information","b":"221–230","g":"ME"}]},{"set":"B","passage":{"title":"My Uncle the Pilot","genre":"draft","paras":["(1) My uncle Faisal is a pilot for a large airline. (2) His first flight which took off from Jeddah was in 2010. (3) He has flown to many cities (including Cairo, Istanbul and Kuala Lumpur. (4) Flying a plane, he says is like solving a puzzle in the sky. (5) Last summer, he took me on a tour of a huge, modern airplane. (6) The cockpit—the place where pilots sit was full of buttons and screens. (7) Someday I hope to become a pilot and I will fly to Tokyo."],"intro":"Tala wrote about her uncle. Her draft has some punctuation mistakes. Read it and answer the questions."},"items":[{"n":1,"t":"mc","s":"What is the correct way to write sentence 2?","o":["His first flight which took off from Jeddah, was in 2010.","His first flight, which took off from Jeddah, was in 2010.","His first flight, which took off from Jeddah was in 2010.","His, first flight which took off from Jeddah was in 2010."],"k":"B","sk":"Uses commas, parentheses or dashes to set off extra information","b":"191–200","g":"ME"},{"n":2,"t":"mc","s":"What is the correct way to write sentence 7?","o":["Someday I hope, to become a pilot and I will fly to Tokyo.","Someday I hope to become, a pilot, and I will fly to Tokyo.","Someday, I hope to become a pilot and, I will fly to Tokyo.","Someday, I hope to become a pilot, and I will fly to Tokyo."],"k":"D","sk":"Uses a comma before a conjunction in a compound sentence","b":"191–200","g":"ME"},{"n":3,"t":"mc","s":"What is the correct way to write the end of sentence 3?","o":["(including Cairo, Istanbul and Kuala Lumpur).","(including Cairo, Istanbul and Kuala Lumpur.","including Cairo, Istanbul and Kuala Lumpur).","(including Cairo, Istanbul and Kuala Lumpur.)"],"k":"A","sk":"Uses commas, parentheses or dashes to set off extra information","b":"201–210","g":"ME"},{"n":4,"t":"mc","s":"What is the correct way to write sentence 4?","o":["Flying, a plane he says is like solving a puzzle in the sky.","Flying a plane he says, is like solving a puzzle in the sky.","Flying a plane, he says, is like solving a puzzle in the sky.","Flying a plane, he says is like solving a puzzle, in the sky."],"k":"C","sk":"Uses commas, parentheses or dashes to set off extra information","b":"201–210","g":"ME"},{"n":5,"t":"mc","s":"Why is there a comma between “huge” and “modern” in sentence 5?","o":["They are coordinate adjectives that describe the airplane equally.","A comma always comes before the last adjective or noun in every sentence.","The word “modern” begins a brand-new and separate part of the sentence.","A comma is needed after every adjective that appears in a sentence."],"k":"A","sk":"Uses commas between coordinate adjectives","b":"211–220","g":"ME"},{"n":6,"t":"mc","s":"What is the correct way to write sentence 6?","o":["The cockpit the place—where pilots sit—was full of buttons and screens.","The cockpit—the place where pilots sit was full—of buttons and screens.","The cockpit—the place where pilots sit—was full of buttons and screens.","—The cockpit the place where pilots sit was full of buttons and screens."],"k":"C","sk":"Uses commas, parentheses or dashes to set off extra information","b":"211–220","g":"ME"},{"n":7,"t":"mc","s":"Which sentence could replace sentence 6 and use commas correctly?","o":["The cockpit, the place where, pilots sit was full of buttons and screens.","The cockpit, the place where pilots sit, was full of buttons and screens.","The cockpit the place, where pilots sit, was full of buttons and screens.","The cockpit, the place where pilots sit was full of buttons, and screens."],"k":"B","sk":"Uses commas, parentheses or dashes to set off extra information","b":"211–220","g":"ME"}]}]},{"id":"U6","title":"Capitalization, Quotations, Titles, Apostrophes and Spelling","goal":"ME","band":"181–220","skills":["Capitalize proper nouns, including names of places, organizations and events","Punctuate direct quotations and recognize indirect quotations","Use italics or quotation marks for titles of works","Use apostrophes correctly and spell commonly misspelled words"],"vocab":[["proper noun","the name of a specific person, place, organization or thing, always capitalized"],["direct quotation","a speaker’s exact words, placed inside quotation marks"],["indirect quotation","a report of what someone said, without the exact words or quotation marks"],["italics","slanted type used for titles of long works such as books and movies"],["possessive","a form that shows ownership, usually with an apostrophe: the girls’ bikes"],["homophones","words that sound alike but have different spellings and meanings: their, there, they’re"]],"sets":[{"set":"A","passage":null,"items":[{"n":1,"t":"mc","s":"Which sentence is capitalized correctly?","o":["Last spring, we visited the National museum in riyadh.","Last spring, we visited the National Museum in Riyadh.","Last Spring, we visited the National Museum in Riyadh.","Last spring, we visited the national museum in Riyadh."],"k":"B","sk":"Capitalizes proper nouns, titles and sentence beginnings","b":"181–190","g":"ME"},{"n":2,"t":"mc","s":"Which word correctly completes the sentence?\n“___ going to the museum on Thursday.”","o":["Their","There","Theyre","They’re"],"k":"D","sk":"Uses apostrophes in contractions and possessives","b":"181–190","g":"ME"},{"n":3,"t":"mc","s":"Which sentence uses an apostrophe correctly?","o":["The two girls bicycle’s were parked outside.","The two girls’s bicycles were parked outside.","The two girls’ bicycles were parked outside.","The two girl’s bicycles were parked outside."],"k":"C","sk":"Uses apostrophes in contractions and possessives","b":"191–200","g":"ME"},{"n":4,"t":"mc","s":"Which title should be written in quotation marks?","o":["an article in a magazine","the title of a full-length movie","the name of a newspaper","the title of a novel"],"k":"A","sk":"Capitalizes and punctuates titles of works","b":"191–200","g":"ME"},{"n":5,"t":"mc","s":"Which sentence is punctuated correctly?","o":["The teacher said “that we should bring our notebooks.”","The teacher said that “we should bring our notebooks.”","The teacher said that we should bring our notebooks.","The teacher said, that we should bring our notebooks."],"k":"C","sk":"Punctuates dialogue and quotations","b":"201–210","g":"ME"},{"n":6,"t":"mc","s":"Which word is spelled correctly?","o":["necessary","necessery","neccessary","nesessary"],"k":"A","sk":"Spells grade-level words correctly","b":"201–210","g":"ME"}]},{"set":"B","passage":{"title":"A Book Review","genre":"draft","paras":["(1) Last week, I finished reading the novel The Secret of the Oasis by Mariam Khalil. (2) The story takes place in a small village near the red sea. (3) The main character, Salim, discovers a map hidden in his grandfathers old trunk. (4) “This map will change everything” Salim whispers to his sister. (5) I especially liked the chapter called The Midnight Storm. (6) The ending was suprising and exciting. (7) I would recommend this book to anyone who likes adventure stories."],"intro":"Abeer wrote a review of a novel. Her draft has some mistakes. Read it and answer the questions."},"items":[{"n":1,"t":"mc","s":"What is the correct way to write “the red sea” in sentence 2?","o":["the Red Sea","the red Sea","the Red sea","The Red sea"],"k":"A","sk":"Capitalizes proper nouns, titles and sentence beginnings","b":"181–190","g":"ME"},{"n":2,"t":"mc","s":"How should the title The Secret of the Oasis in sentence 1 be written in a typed review?","o":["in quotation marks","in italics","in all capital letters","in parentheses"],"k":"B","sk":"Capitalizes and punctuates titles of works","b":"191–200","g":"ME"},{"n":3,"t":"mc","s":"How should “grandfathers” in sentence 3 be written?","o":["grandfathers’s","grandfathers’","grandfather’s’","grandfather’s"],"k":"D","sk":"Uses apostrophes in contractions and possessives","b":"191–200","g":"ME"},{"n":4,"t":"mc","s":"Which word should replace “suprising” in sentence 6?","o":["suprizing","surprizing","surprising","surpriseing"],"k":"C","sk":"Spells grade-level words correctly","b":"191–200","g":"ME"},{"n":5,"t":"mc","s":"What is the correct way to write sentence 4?","o":["“This map will change everything” Salim whispers, to his sister.","“This map will change everything, Salim whispers to his sister.”","“This map will change everything.” Salim whispers to his sister.","“This map will change everything,” Salim whispers to his sister."],"k":"D","sk":"Punctuates dialogue and quotations","b":"201–210","g":"ME"},{"n":6,"t":"mc","s":"Which sentence about the review is written correctly?","o":["Abeer’s review will appear in the school’s newsletter.","Abeers review will appear in the school’s newsletter.","Abeer’s review will appear in the schools newsletter.","Abeers’ review will appear in the school’s newsletter."],"k":"A","sk":"Uses apostrophes in contractions and possessives","b":"201–210","g":"ME"},{"n":7,"t":"mc","s":"How should the chapter title The Midnight Storm in sentence 5 be written?","o":["underlined","in italics","in quotation marks","in all capital letters"],"k":"C","sk":"Capitalizes and punctuates titles of works","b":"211–220","g":"ME"}]}]}],"mocks":[{"id":"A","note":"Full practice test · 43 questions","sections":[{"passage":{"title":"The Silk Road","genre":"draft","paras":["(1) The Silk Road was not a single road. (2) It was a network of trade routes that connected China with the lands around the Mediterranean Sea. (3) Merchants carried silk, spices, paper and glass across deserts and mountains. (4) Along the way, they also shared ideas, religions and inventions. (5) Cities such as Samarkand and Baghdad grows rich because of this trade. (6) The name “Silk Road” was created by a german geographer in 1877. (7) Today, historians agree that these routes changed the world."],"intro":"Nouf is writing a history report. Read her draft and answer the questions."},"items":[{"n":1,"t":"mc","s":"Which word should replace “grows” in sentence 5?","o":["growing","grew","grow","has grown"],"k":"B","sk":"Avoids inappropriate shifts in verb tense","b":"181–190","g":"GU"},{"n":2,"t":"mc","s":"What is the correct way to write the end of sentence 6?","o":["by a GERMAN geographer in 1877.","by a German Geographer in 1877.","by a german Geographer in 1877.","by a German geographer in 1877."],"k":"D","sk":"Capitalizes proper nouns, titles and sentence beginnings","b":"181–190","g":"ME"},{"n":3,"t":"mc","s":"Which sentence would make the BEST hook before sentence 1?","o":["Imagine a journey of thousands of kilometers, made by camel, to sell a bolt of silk.","This report is going to be about the Silk Road and some of the facts about the Silk Road.","Roads are paths that people use to travel from one place to another place in the world.","The Silk Road is a topic that I chose to write about for my history class this term."],"k":"A","sk":"Chooses an effective introduction","b":"191–200","g":"WR"},{"n":4,"t":"mc","s":"Which sentence would BEST follow sentence 4 to give an example?","o":["Merchants today often use large ships, fast trains and trucks to move their goods around.","Silk is a smooth and shiny cloth that is made from the fine threads spun by silkworms.","For example, the art of papermaking spread from China to the Middle East along these routes.","Deserts can be very hot during the day and surprisingly cold during the night as well."],"k":"C","sk":"Adds a detail that supports the main idea","b":"191–200","g":"WR"},{"n":5,"t":"mc","s":"Nouf wants to add a sentence about the dangers that merchants faced on their journeys. Where would it fit BEST?","o":["after sentence 3","after sentence 5","after sentence 6","after sentence 7"],"k":"A","sk":"Puts sentences or events in a logical order","b":"191–200","g":"WR"},{"n":6,"t":"mc","s":"Which sentence would BEST replace sentence 7 as a conclusion?","o":["Many people still buy and wear silk scarves, shirts and dresses in many countries.","The Silk Road was in use for a very long time in the past, which is long ago.","Samarkand is a city in Uzbekistan that has beautiful buildings with blue tiles.","By linking distant peoples, the Silk Road helped shape the history of the world."],"k":"D","sk":"Chooses an effective concluding sentence","b":"191–200","g":"WR"}]},{"passage":{"title":"The Missing Notebook","genre":"draft","paras":["(1) On the morning of the science quiz, my notebook was gone. (2) I searched my backpack, my desk and even the trash can. (3) “Did you check the library?” asked my friend Ziyad. (4) I remembered that I had studied there the day before. (5) I ran down the hall as fast as I can. (6) The librarian smiled and held up a blue notebook. (7) “I believe this belongs to you” she said."],"intro":"Ahmad is writing a story. Read his draft and answer the questions."},"items":[{"n":7,"t":"mc","s":"Which word should replace “can” in sentence 5?","o":["cans","could","will","may"],"k":"B","sk":"Uses modal auxiliaries","b":"181–190","g":"GU"},{"n":8,"t":"mc","s":"Which transition could BEST begin sentence 4?","o":["In conclusion,","For example,","Suddenly,","On the other hand,"],"k":"C","sk":"Chooses a transition that connects ideas","b":"181–190","g":"WR"},{"n":9,"t":"mc","s":"What is the correct way to write sentence 7?","o":["“I believe this belongs to you.” she said.","“I believe this belongs to you,” she said.","“I believe this belongs to you, she said.”","“I believe this belongs to you” she said."],"k":"B","sk":"Punctuates dialogue and quotations","b":"191–200","g":"ME"},{"n":10,"t":"mc","s":"Which revision of sentence 2 BEST shows Ahmad’s panic?","o":["I looked in my backpack, and I looked in my desk, and I also looked in the trash.","I checked my backpack and my desk, and then I checked the trash can in the room.","I tore through my backpack, yanked open my desk and even dug through the trash can.","I searched my backpack, which is blue, and my desk, which is brown, and the trash."],"k":"C","sk":"Chooses precise or vivid language","b":"191–200","g":"WR"},{"n":11,"t":"mc","s":"What is the purpose of the dialogue in sentence 3?","o":["to show that Ziyad is angry with Ahmad about the quiz","to describe what the library looks like inside","to explain the rules for taking a science quiz","to give Ahmad an idea that moves the story forward"],"k":"D","sk":"Uses narrative techniques: dialogue, description and pacing","b":"191–200","g":"WR"},{"n":12,"t":"mc","s":"Which sentence would be the BEST ending for the story?","o":["I hugged the notebook and hurried to class, just as the bell began to ring.","Notebooks can be bought at most stationery stores for a few riyals each.","The library has thousands of books about science, history, art and many other subjects.","Science quizzes usually have about ten questions about the lessons of the week."],"k":"A","sk":"Chooses an effective concluding sentence","b":"191–200","g":"WR"}]},{"passage":{"title":"Phones in Class","genre":"draft","paras":["(1) Many schools ban phones in class, but I believe students should be allowed to use them for learning. (2) Phones give students quick access to dictionaries, maps and educational videos. (3) They also helps students stay organized with calendars and reminders. (4) Critics argue that phones distract students from their lessons. (5) However, teachers can set clear rules, such as keeping phones face down until they are needed. (6) Phones are made by many different companies around the world. (7) With the right rules phones can become powerful tools for learning."],"intro":"Lina wrote an argument essay. Read her draft and answer the questions."},"items":[{"n":13,"t":"mc","s":"Which sentence states Lina’s claim?","o":["sentence 1","sentence 2","sentence 4","sentence 5"],"k":"A","sk":"States a clear claim or thesis","b":"181–190","g":"WR"},{"n":14,"t":"mc","s":"Which word should replace “helps” in sentence 3?","o":["is helping","helping","help","has helped"],"k":"C","sk":"Makes subjects and verbs agree","b":"181–190","g":"GU"},{"n":15,"t":"mc","s":"Which sentence should be removed because it is not relevant to the argument?","o":["sentence 2","sentence 3","sentence 5","sentence 6"],"k":"D","sk":"Identifies a sentence that does not belong","b":"191–200","g":"WR"},{"n":16,"t":"mc","s":"Where should a comma be added in sentence 7?","o":["after “phones”","after “rules”","after “With”","after “powerful”"],"k":"B","sk":"Uses a comma after an introductory word, phrase or clause","b":"191–200","g":"ME"},{"n":17,"t":"mc","s":"What is the purpose of sentence 5?","o":["to introduce the writer’s main claim","to summarize the whole essay for the reader","to give a second reason that supports sentence 2","to respond to the counterclaim in sentence 4"],"k":"D","sk":"Acknowledges and answers an opposing claim","b":"191–200","g":"WR"},{"n":18,"t":"mc","s":"Which piece of evidence would BEST support sentence 2?","o":["In one school survey, 70 percent of students said they used phones to look up new words.","Phones were first sold to the public in the 1980s, and they were very heavy back then.","Most phones today come with cameras that can take very clear photographs at night.","Some students prefer phones with large screens, and others prefer much smaller ones."],"k":"A","sk":"Chooses relevant evidence to support a point","b":"191–200","g":"WR"}]},{"passage":null,"items":[{"n":19,"t":"mc","s":"Which sentence is MOST appropriate for a formal science report?","o":["Honestly, the plants were kind of a disaster without sunlight.","The plants totally needed way more sunlight, if you ask me.","The results suggest that the plants needed more sunlight to grow.","Our plants were super sad because they did not get much sun."],"k":"C","sk":"Keeps a consistent formal style and objective tone","b":"191–200","g":"WR"},{"n":20,"t":"mc","s":"Which sentence BEST introduces a cause-and-effect paragraph about erosion?","o":["Rocks can be many different colors, such as red, gray, brown, black and even white.","Wind and water slowly wear away rock, and this process changes the shape of the land.","There are three main types of rocks: igneous, sedimentary and metamorphic rocks.","Many people enjoy climbing large rocks on weekends with their families and friends."],"k":"B","sk":"Chooses a topic sentence that introduces the main idea","b":"191–200","g":"WR"},{"n":21,"t":"mc","s":"Read this sentence from a source.\n“Peregrine falcons can reach speeds of more than 300 kilometers per hour when they dive.”\nWhich sentence is a correct paraphrase?","o":["When diving, a peregrine falcon can fly faster than 300 kilometers an hour.","A peregrine falcon dives about 300 times every hour when it is hunting for food.","Peregrine falcons can reach speeds of more than 300 kilometers per hour when they dive.","Peregrine falcons can fly 300 kilometers without stopping once they begin to dive."],"k":"A","sk":"Paraphrases or cites a source correctly","b":"191–200","g":"WR"}],"label":"Writing"},{"passage":null,"items":[{"n":22,"t":"mc","s":"Which pronoun correctly completes the sentence?\n“Hamad and ___ are working on the project together.”","o":["his","himself","him","he"],"k":"D","sk":"Uses the correct pronoun case","b":"181–190","g":"GU"},{"n":23,"t":"mc","s":"Which pronoun correctly completes the sentence?\n“The teacher asked Rana and ___ to hand out the papers.”","o":["herself","she","her","hers"],"k":"C","sk":"Uses the correct pronoun case","b":"191–200","g":"GU"},{"n":24,"t":"mc","s":"Which sentence uses an intensive pronoun?","o":["My mother and I painted the fence.","I painted the whole fence myself.","I painted the whole fence for my mother.","The fence was painted by my mother."],"k":"B","sk":"Uses reflexive and intensive pronouns","b":"191–200","g":"GU"},{"n":25,"t":"mc","s":"Which word correctly completes the sentence?\n“One of my friends ___ a new bicycle.”","o":["are having","have","were having","has"],"k":"D","sk":"Makes subjects and verbs agree","b":"191–200","g":"GU"},{"n":26,"t":"mc","s":"Which sentence is a compound sentence?","o":["The bell rang loudly at the end of the long day.","The bell rang, and the students left the room.","The students left the room after the bell rang.","When the bell rang, the students left the room."],"k":"B","sk":"Forms simple, compound and complex sentences","b":"191–200","g":"GU"},{"n":27,"t":"mc","s":"Which word correctly completes the sentence?\n“Please ___ my apology for being late.”","o":["accept","except","expect","excepts"],"k":"A","sk":"Chooses between frequently confused words","b":"191–200","g":"GU"},{"n":28,"t":"mc","s":"Which sentence has an incorrect shift in pronoun person?","o":["If we want to stay healthy, we should exercise daily.","If you want to stay healthy, you should exercise daily.","If people want to stay healthy, you should exercise daily.","If people want to stay healthy, they should exercise daily."],"k":"C","sk":"Makes pronouns agree with their antecedents","b":"191–200","g":"GU"},{"n":29,"t":"mc","s":"Which words correctly complete the sentence?\n“By the time the guests arrived, we ___ the house.”","o":["cleaning","will clean","had cleaned","have cleaned"],"k":"C","sk":"Uses perfect verb tenses","b":"191–200","g":"GU"},{"n":30,"t":"mc","s":"Which is the BEST way to combine the sentences?\n“The storm was strong. The trees did not fall.”","o":["The storm was strong, so the trees did not fall.","The storm was strong, the trees did not fall.","Because the storm was strong, the trees did not fall.","Although the storm was strong, the trees did not fall."],"k":"D","sk":"Combines sentences correctly","b":"191–200","g":"GU"},{"n":31,"t":"mc","s":"Which word correctly completes the sentence?\n“The student ___ won the spelling bee is my cousin.”","o":["whom","who","whose","which"],"k":"B","sk":"Uses relative pronouns and relative adverbs","b":"191–200","g":"GU"},{"n":32,"t":"mc","s":"Which sentence has a vague pronoun?","o":["When Omar called Faisal, he was at the mall.","Omar was at the mall when he called Faisal.","When Omar called Faisal, Omar was at the mall.","Omar called Faisal while Faisal was at the mall."],"k":"A","sk":"Corrects vague or unclear pronouns","b":"211–220","g":"GU"}],"label":"Grammar and Usage"},{"passage":null,"items":[{"n":33,"t":"mc","s":"Which sentence uses commas correctly?","o":["Our new neighbor, Mr. Saleh, is a chef.","Our new neighbor, Mr. Saleh is a chef.","Our, new neighbor Mr. Saleh is a chef.","Our new neighbor Mr. Saleh, is a chef."],"k":"A","sk":"Uses commas, parentheses or dashes to set off extra information","b":"181–190","g":"ME"},{"n":34,"t":"mc","s":"Which sentence is capitalized correctly?","o":["We celebrated eid al-fitr with our grandparents.","we celebrated Eid al-Fitr with our grandparents.","We celebrated Eid al-Fitr with our grandparents.","We celebrated Eid Al-fitr with our Grandparents."],"k":"C","sk":"Capitalizes proper nouns, titles and sentence beginnings","b":"181–190","g":"ME"},{"n":35,"t":"mc","s":"Which sentence uses a comma correctly?","o":["Before the race began the runners, stretched.","Before the race, began the runners stretched.","Before, the race began the runners stretched.","Before the race began, the runners stretched."],"k":"D","sk":"Uses a comma after an introductory word, phrase or clause","b":"181–190","g":"ME"},{"n":36,"t":"mc","s":"Which sentence uses commas correctly?","o":["The cold, dark, cave was silent.","The cold, dark cave was silent.","The cold dark, cave was silent.","The, cold dark cave was silent."],"k":"B","sk":"Uses commas between coordinate adjectives","b":"191–200","g":"ME"},{"n":37,"t":"mc","s":"Which sentence uses parentheses correctly?","o":["(Ali’s best friend) the boy in the red shirt is on our team.","Ali’s best friend (the boy in the red shirt) is on our team.","Ali’s best friend (the boy in the red shirt is on our team).","Ali’s best friend the boy (in the red shirt) is on our team."],"k":"B","sk":"Uses commas, parentheses or dashes to set off extra information","b":"191–200","g":"ME"},{"n":38,"t":"mc","s":"Which sentence is punctuated correctly?","o":["Where are you going? “asked Mother.”","“Where are you going?” Asked Mother.","“Where are you going?” asked Mother.","“Where are you going,” asked Mother?"],"k":"C","sk":"Punctuates dialogue and quotations","b":"191–200","g":"ME"},{"n":39,"t":"mc","s":"Which sentence uses an apostrophe correctly?","o":["The womens team won the championship.","The womens’ team won the championship.","The women’s’ team won the championship.","The women’s team won the championship."],"k":"D","sk":"Uses apostrophes in contractions and possessives","b":"191–200","g":"ME"},{"n":40,"t":"mc","s":"Which sentence uses a dash correctly?","o":["There was only one thing left to do—run!","There—was only one thing left to do run!","There was only one thing—left to do run!","There was only one—thing left to do run!"],"k":"A","sk":"Uses hyphens and dashes correctly","b":"191–200","g":"ME"},{"n":41,"t":"mc","s":"Which title should be written in italics or underlined?","o":["the title of a play","the title of a short story","the title of a chapter","the title of a poem"],"k":"A","sk":"Capitalizes and punctuates titles of works","b":"191–200","g":"ME"},{"n":42,"t":"mc","s":"Which word is spelled correctly?","o":["separete","seperate","seprate","separate"],"k":"D","sk":"Spells grade-level words correctly","b":"191–200","g":"ME"},{"n":43,"t":"mc","s":"Which sentence is punctuated correctly?","o":["My grandfather, who lives in Taif grows roses.","My grandfather, who lives in Taif, grows roses.","My grandfather who lives in Taif, grows roses.","My grandfather who, lives in Taif grows roses."],"k":"B","sk":"Uses commas, parentheses or dashes to set off extra information","b":"191–200","g":"ME"}],"label":"Capitalization, Punctuation and Spelling"}]},{"id":"B","note":"Full practice test · 43 questions","sections":[{"passage":{"title":"Al-Khwarizmi and the Birth of Algebra","genre":"draft","paras":["(1) Muhammad ibn Musa al-Khwarizmi was a mathematician who lived about 1,200 years ago. (2) He worked at the House of Wisdom, a famous center of learning in Baghdad. (3) There, scholars translated and studied books from Greece Persia and India. (4) Al-Khwarizmi wrote a book that explained how to solve equations step by step. (5) The word “algebra” comes from al-jabr, a word in the title of his book. (6) Even the word “algorithm” comes from his name. (7) Today, computer programmers uses algorithms every day."],"intro":"Yazeed is writing a report about a famous scientist. Read his draft and answer the questions."},"items":[{"n":1,"t":"mc","s":"Where should a comma be added in sentence 3?","o":["after “Greece”","after “studied”","after “translated”","after “books”"],"k":"A","sk":"Uses commas in a series","b":"181–190","g":"ME"},{"n":2,"t":"mc","s":"Which word should replace “uses” in sentence 7?","o":["using","has used","use","is using"],"k":"C","sk":"Makes subjects and verbs agree","b":"191–200","g":"GU"},{"n":3,"t":"mc","s":"Which sentence BEST states the main idea of the report?","o":["Books from Greece, Persia and India were very popular.","Al-Khwarizmi’s work in mathematics still affects the modern world.","Baghdad was a large and busy city about 1,200 years ago.","Mathematics is a subject that some students find very difficult to learn."],"k":"B","sk":"Chooses a topic sentence that introduces the main idea","b":"191–200","g":"WR"},{"n":4,"t":"mc","s":"Which transition would BEST begin sentence 4 to connect it to sentence 3?","o":["On the other hand,","As a result,","In contrast,","Among these scholars,"],"k":"D","sk":"Chooses a transition that connects ideas","b":"201–210","g":"WR"},{"n":5,"t":"mc","s":"Which sentence would BEST follow sentence 7 to help readers understand the word “algorithm”?","o":["Many students enjoy playing games on computers after finishing homework.","An algorithm is a set of steps that tells a computer how to solve a problem.","Computers come in many sizes, from huge machines to tiny phones in pockets.","Programmers often work in offices, and some of them work from their homes."],"k":"B","sk":"Adds a detail that supports the main idea","b":"201–210","g":"WR"},{"n":6,"t":"mc","s":"Yazeed wants to find out when al-Khwarizmi was born. Which source is the MOST reliable?","o":["a history of science encyclopedia written by experts","a video game that features famous scientists as characters","a comic book about a time-traveling mathematician","a social media post with no author or date listed"],"k":"A","sk":"Chooses a useful source or research question","b":"201–210","g":"WR"}]},{"passage":{"title":"The Camping Trip","genre":"draft","paras":["(1) The sun was sinking behind the dunes when we finished setting up our tent. (2) My father lit a small fire, and my brother and I gathered around it. (3) Suddenly, we heard a strange sound coming from the darkness. (4) “What was that” my brother whispered. (5) Dad shined his flashlight toward the noise. (6) Two shining eyes stared back at us—it was a desert fox! (7) It looked at us for a moment, and then it disappears into the night."],"intro":"Joud is writing a personal narrative. Read her draft and answer the questions."},"items":[{"n":7,"t":"mc","s":"Which sentence BEST describes the setting of the story?","o":["sentence 1","sentence 3","sentence 5","sentence 7"],"k":"A","sk":"Uses narrative techniques: dialogue, description and pacing","b":"181–190","g":"WR"},{"n":8,"t":"mc","s":"Which transition could BEST begin sentence 5?","o":["However,","In conclusion,","Quickly,","For example,"],"k":"C","sk":"Chooses a transition that connects ideas","b":"181–190","g":"WR"},{"n":9,"t":"mc","s":"What is the correct way to write sentence 4?","o":["“What was that,” my brother whispered?","“What was that.” my brother whispered.","“What was that?” My brother whispered.","“What was that?” my brother whispered."],"k":"D","sk":"Punctuates dialogue and quotations","b":"191–200","g":"ME"},{"n":10,"t":"mc","s":"Which word should replace “disappears” in sentence 7?","o":["will disappear","has disappeared","disappeared","disappearing"],"k":"C","sk":"Avoids inappropriate shifts in verb tense","b":"191–200","g":"GU"},{"n":11,"t":"mc","s":"Which revision of sentence 5 BEST slows the pace to build suspense?","o":["Dad shined the flashlight toward the strange noise that all of us had heard a moment before.","Dad quickly shined his flashlight, which was a brand-new one, toward the place of the noise.","Dad shined his flashlight toward the noise, and then he shined it some more after that.","Dad slowly raised his flashlight, and its beam crept across the sand toward the noise."],"k":"D","sk":"Uses narrative techniques: dialogue, description and pacing","b":"201–210","g":"WR"},{"n":12,"t":"mc","s":"Which sentence would be the BEST ending for the narrative?","o":["Our tent was green and had room for four people and all of their bags.","As I fell asleep that night, I kept thinking about those bright eyes in the dark.","Camping is a popular activity in the winter months, when the desert is much cooler.","Desert foxes have very large ears that help them hear well and also help them stay cool."],"k":"B","sk":"Chooses an effective concluding sentence","b":"201–210","g":"WR"}]},{"passage":{"title":"A Letter to the City Council","genre":"draft","paras":["Dear Members of the City Council:","(1) I am writing to ask the council to add bike lanes on king Abdullah road. (2) Many students in my neighborhood would like to ride their bikes to school. (3) However, the road is busy, and drivers often go fast. (4) Bike lanes would make the road more safer for everyone. (5) They would also reduce traffic, because fewer parents would need to drive. (6) Some people worry that bike lanes will take space away from cars. (7) The road is wide enough to add narrow lanes without removing any car lanes.","Sincerely,","Talal Al-Harbi"],"intro":"Talal wrote a letter to the city council. Read his draft and answer the questions."},"items":[{"n":13,"t":"mc","s":"What is the main purpose of Talal’s letter?","o":["to explain how to ride a bike safely in heavy traffic","to persuade the council to add bike lanes on a busy road","to describe the history of King Abdullah Road in the city","to thank the council for building a new school nearby"],"k":"B","sk":"Chooses language that fits the purpose and audience","b":"181–190","g":"WR"},{"n":14,"t":"mc","s":"What is the correct way to write the end of sentence 1?","o":["on King Abdullah road.","on king abdullah Road.","on king Abdullah road.","on King Abdullah Road."],"k":"D","sk":"Capitalizes proper nouns, titles and sentence beginnings","b":"181–190","g":"ME"},{"n":15,"t":"mc","s":"What is the correct way to write sentence 4?","o":["Bike lanes would make the road safest for everyone.","Bike lanes would make the road most safer for everyone.","Bike lanes would make the road safer for everyone.","Bike lanes would make the road more safe-er for everyone."],"k":"C","sk":"Uses adjectives and adverbs correctly, including comparisons","b":"191–200","g":"GU"},{"n":16,"t":"mc","s":"Which transition would BEST begin sentence 7 to answer the concern in sentence 6?","o":["Fortunately,","For example,","Similarly,","In addition,"],"k":"A","sk":"Acknowledges and answers an opposing claim","b":"191–200","g":"WR"},{"n":17,"t":"mc","s":"Which piece of evidence would BEST support sentence 3?","o":["Many families in the neighborhood own two or more cars and at least one bicycle.","King Abdullah Road was built many years ago and has tall palm trees growing along both sides.","Some students prefer to walk to school with their friends in the early morning.","A city traffic study found that cars on this road often go faster than the speed limit."],"k":"D","sk":"Chooses relevant evidence to support a point","b":"201–210","g":"WR"},{"n":18,"t":"mc","s":"Which sentence would be the BEST closing for the letter?","o":["Thank you for considering this request, which would help keep students safe.","Please write back soon, because I am waiting and I do not like to wait.","Bikes are fun, and riding them is a great way to spend a sunny afternoon.","If you do not add the bike lanes, I will be very upset with all of you."],"k":"A","sk":"Keeps a consistent formal style and objective tone","b":"211–220","g":"WR"}]},{"passage":null,"items":[{"n":19,"t":"mc","s":"Which sentence is the MOST concise?","o":["The meeting, which was a meeting, was canceled because of the storm that was stormy.","The meeting was canceled because of the storm.","The meeting was canceled, and the reason it was canceled was because of the storm.","Because of the storm, the meeting was canceled, and it was canceled due to the storm."],"k":"B","sk":"Revises to remove wordy or repeated language","b":"191–200","g":"WR"},{"n":20,"t":"mc","s":"A student is writing an informative essay about how to save water at home. Which detail is MOST relevant?","o":["Some people prefer to drink cold sparkling water instead of plain water with meals.","The Arabian Gulf and the Red Sea are both large bodies of salt water.","Fixing a dripping faucet can save thousands of liters of water each year.","Water covers about seventy percent of the surface of the planet Earth."],"k":"C","sk":"Chooses relevant evidence to support a point","b":"201–210","g":"WR"},{"n":21,"t":"mc","s":"Which sentence BEST uses domain-specific vocabulary for a science report about volcanoes?","o":["Really hot melted things come out of mountains sometimes.","Hot stuff comes up from deep inside and pours out of the top.","Magma rises through cracks in the crust and erupts as lava.","Volcanoes do cool things when they blow up and get loud."],"k":"C","sk":"Chooses precise or vivid language","b":"211–220","g":"WR"}],"label":"Writing"},{"passage":null,"items":[{"n":22,"t":"mc","s":"Which pronoun correctly completes the sentence?\n“Mona and ___ walked to the bakery.”","o":["hers","she","herself","her"],"k":"B","sk":"Uses the correct pronoun case","b":"181–190","g":"GU"},{"n":23,"t":"mc","s":"Which word correctly completes the sentence?\n“The dog wagged ___ tail when it saw us.”","o":["their","there","it’s","its"],"k":"D","sk":"Makes pronouns agree with their antecedents","b":"181–190","g":"GU"},{"n":24,"t":"mc","s":"Which of these is a run-on sentence?","o":["I finished my homework I watched a movie.","I finished my homework, and then I watched a movie.","After I finished my homework, I watched a movie.","I watched a movie after finishing my homework."],"k":"A","sk":"Recognizes complete sentences, fragments and run-ons","b":"181–190","g":"GU"},{"n":25,"t":"mc","s":"Which sentence uses an intensive pronoun correctly?","o":["Us ourselves planned the entire party.","We planned the entire party for ourself.","We ourselves planned the entire party.","Ourselves planned the entire party."],"k":"C","sk":"Uses reflexive and intensive pronouns","b":"191–200","g":"GU"},{"n":26,"t":"mc","s":"Which word correctly completes the sentence?\n“The basket of oranges ___ on the table.”","o":["have sat","sits","sit","are sitting"],"k":"B","sk":"Makes subjects and verbs agree","b":"191–200","g":"GU"},{"n":27,"t":"mc","s":"Which sentence uses the word “then” correctly?","o":["We ate dinner, and then we went for a walk.","She runs faster then anyone in our class.","My cat is much bigger then your cat.","This book is better then the movie."],"k":"A","sk":"Chooses between frequently confused words","b":"191–200","g":"GU"},{"n":28,"t":"mc","s":"Which pronoun correctly completes the sentence?\n“Everyone except ___ passed the swimming test.”","o":["himself","his","he","him"],"k":"D","sk":"Uses the correct pronoun case","b":"201–210","g":"GU"},{"n":29,"t":"mc","s":"Which word correctly completes the sentence?\n“Neither Sami nor his sisters ___ been to Paris.”","o":["have","was","has","is"],"k":"A","sk":"Uses correlative conjunctions","b":"201–210","g":"GU"},{"n":30,"t":"mc","s":"Which sentence has a vague pronoun?","o":["The students learned from their teachers about the upcoming trip.","The teachers told the students that they would be going on a trip.","The teachers told the students that the class would go on a trip.","The teachers told the students, “You will be going on a trip.”"],"k":"B","sk":"Corrects vague or unclear pronouns","b":"211–220","g":"GU"},{"n":31,"t":"mc","s":"Which words correctly complete the sentence?\n“If you ___ harder, you would have passed the test.”","o":["would study","have studied","studied","had studied"],"k":"D","sk":"Uses perfect verb tenses","b":"211–220","g":"GU"},{"n":32,"t":"mc","s":"Which sentence is written in standard English?","o":["There is fewer cars on the road today.","There are less cars on the road today.","There are fewer cars on the road today.","There is less cars on the road today."],"k":"C","sk":"Chooses between frequently confused words","b":"211–220","g":"GU"}],"label":"Grammar and Usage"},{"passage":null,"items":[{"n":33,"t":"mc","s":"Which sentence uses a comma correctly?","o":["Yes, I will join the debate club.","Yes I will join, the debate club.","Yes I will, join the debate club.","Yes I, will join the debate club."],"k":"A","sk":"Uses a comma after an introductory word, phrase or clause","b":"181–190","g":"ME"},{"n":34,"t":"mc","s":"Which sentence uses a comma correctly?","o":["The test was difficult but, most students passed.","The test was difficult, but most students passed.","The test, was difficult but most students passed.","The test was difficult but most, students passed."],"k":"B","sk":"Uses a comma before a conjunction in a compound sentence","b":"181–190","g":"ME"},{"n":35,"t":"mc","s":"Which sentence is capitalized correctly?","o":["My family drove South to visit the Asir Mountains.","My family drove south to visit the Asir mountains.","my family drove south to visit the asir mountains.","My family drove south to visit the Asir Mountains."],"k":"D","sk":"Capitalizes proper nouns, titles and sentence beginnings","b":"191–200","g":"ME"},{"n":36,"t":"mc","s":"Which sentence uses commas correctly?","o":["The, tall friendly librarian helped us find the book.","The tall, friendly, librarian helped us find the book.","The tall, friendly librarian helped us find the book.","The tall friendly, librarian helped us find the book."],"k":"C","sk":"Uses commas between coordinate adjectives","b":"191–200","g":"ME"},{"n":37,"t":"mc","s":"Which sentence uses commas correctly?","o":["Riyadh the capital of Saudi Arabia, is a growing city.","Riyadh, the capital of Saudi Arabia is a growing city.","Riyadh the capital, of Saudi Arabia is a growing city.","Riyadh, the capital of Saudi Arabia, is a growing city."],"k":"D","sk":"Uses commas, parentheses or dashes to set off extra information","b":"191–200","g":"ME"},{"n":38,"t":"mc","s":"Which sentence is written correctly?","o":["We read the Poem “Desert Rain” in class.","We read the poem “desert rain” in class.","We read the poem “Desert Rain” in class.","We read the poem Desert Rain in class."],"k":"C","sk":"Capitalizes and punctuates titles of works","b":"191–200","g":"ME"},{"n":39,"t":"mc","s":"Which sentence uses dashes correctly?","o":["My favorite food—grilled fish is served—on Fridays.","My favorite food—grilled fish—is served on Fridays.","—My favorite food grilled fish is served on Fridays.","My favorite—food grilled fish—is served on Fridays."],"k":"B","sk":"Uses commas, parentheses or dashes to set off extra information","b":"201–210","g":"ME"},{"n":40,"t":"mc","s":"Which sentence is punctuated correctly?","o":["“I think,” said Dana, “that we should leave now.”","“I think,” said Dana “that we should leave now.”","“I think” said Dana, “that we should leave now.”","“I think,” said Dana, “That we should leave now.”"],"k":"A","sk":"Punctuates dialogue and quotations","b":"201–210","g":"ME"},{"n":41,"t":"mc","s":"Which sentence uses apostrophes correctly?","o":["Its time to give the cat it’s dinner.","It’s time to give the cat it’s dinner.","Its time to give the cat its’ dinner.","It’s time to give the cat its dinner."],"k":"D","sk":"Uses apostrophes in contractions and possessives","b":"201–210","g":"ME"},{"n":42,"t":"mc","s":"Which word is spelled correctly?","o":["occassion","occasion","ocasion","ocassion"],"k":"B","sk":"Spells grade-level words correctly","b":"201–210","g":"ME"},{"n":43,"t":"mc","s":"Which word is spelled correctly?","o":["government","goverment","governmint","guvernment"],"k":"A","sk":"Spells grade-level words correctly","b":"211–220","g":"ME"}],"label":"Capitalization, Punctuation and Spelling"}]},{"id":"C","note":"Full practice test · 43 questions · harder","sections":[{"passage":{"title":"Earthquakes","genre":"draft","paras":["(1) The ground beneath our feet may seem solid, but it is always moving. (2) Earth’s outer layer is broken into giant pieces called tectonic plates. (3) These plates slowly push against each other, pull apart or sliding past each other. (4) Sometimes the plates get stuck, and pressure builds up. (5) When the plates suddenly slip, the energy is released as an earthquake. (6) Scientists measure earthquakes with an instrument called a seismometer. (7) Although scientists cannot yet predict earthquakes they can help people prepare for them."],"intro":"Hamza is writing a science report. Read his draft and answer the questions."},"items":[{"n":1,"t":"mc","s":"Which word in sentence 7 signals a contrast?","o":["predict","cannot","Although","prepare"],"k":"C","sk":"Chooses a transition that connects ideas","b":"191–200","g":"WR"},{"n":2,"t":"mc","s":"Which sentence BEST states the main idea of the report?","o":["Earthquakes happen when moving plates release built-up energy.","Some buildings are taller than others, and some are much older.","Scientists work in many different fields, such as biology and chemistry.","The ground is made of soil, sand, clay and small pieces of rock."],"k":"A","sk":"Chooses a topic sentence that introduces the main idea","b":"191–200","g":"WR"},{"n":3,"t":"mc","s":"Where should a comma be added in sentence 7?","o":["after “people”","after “scientists”","after “Although”","after “earthquakes”"],"k":"D","sk":"Uses a comma after an introductory word, phrase or clause","b":"191–200","g":"ME"},{"n":4,"t":"mc","s":"Which word should replace “sliding” in sentence 3?","o":["to sliding","slide","slid","slides"],"k":"B","sk":"Uses parallel structure","b":"201–210","g":"GU"},{"n":5,"t":"mc","s":"Which detail would BEST follow sentence 6?","o":["The word “instrument” can also describe a violin, a drum or a flute.","Some people feel nervous when they hear about earthquakes in the news.","Many scientists study at universities for several years before working.","The instrument records how strongly and how long the ground shakes."],"k":"D","sk":"Adds a detail that supports the main idea","b":"201–210","g":"WR"},{"n":6,"t":"mc","s":"Hamza wants to add a sentence telling readers how to stay safe during an earthquake. Where should it go?","o":["after sentence 1","after sentence 2","after sentence 4","after sentence 7"],"k":"D","sk":"Puts sentences or events in a logical order","b":"211–220","g":"WR"}]},{"passage":{"title":"The Lost Falcon","genre":"draft","paras":["(1) My grandfather has trained falcons for forty years. (2) One windy afternoon, his favorite falcon, Shaheen, flew off and did not return. (3) We searched the desert until the sun begins to set. (4) Grandfather lifted his leather glove and whistled one long, sharp note. (5) For a moment, nothing happened. (6) Then a dark shape appeared against the orange sky. (7) Shaheen landed gently on the glove, and grandfather smiled."],"intro":"Nasser is writing a story. Read his draft and answer the questions."},"items":[{"n":7,"t":"mc","s":"Which sentence introduces the main problem of the story?","o":["sentence 1","sentence 2","sentence 4","sentence 7"],"k":"B","sk":"Uses narrative techniques: dialogue, description and pacing","b":"181–190","g":"WR"},{"n":8,"t":"mc","s":"Which word should replace “begins” in sentence 3?","o":["began","beginning","has begun","will begin"],"k":"A","sk":"Avoids inappropriate shifts in verb tense","b":"191–200","g":"GU"},{"n":9,"t":"mc","s":"Which word could replace “appeared” in sentence 6 to make the description more vivid?","o":["went","was","emerged","came"],"k":"C","sk":"Chooses precise or vivid language","b":"191–200","g":"WR"},{"n":10,"t":"mc","s":"What is the correct way to write the end of sentence 7?","o":["and grandfather Smiled.","and Grandfather smiled.","and GrandFather smiled.","And grandfather smiled."],"k":"B","sk":"Capitalizes proper nouns, titles and sentence beginnings","b":"201–210","g":"ME"},{"n":11,"t":"mc","s":"Why does Nasser use the short sentence 5?","o":["to show that grandfather is angry","to explain how falcons are trained","to create a pause that builds suspense","to describe what the desert looks like"],"k":"C","sk":"Uses narrative techniques: dialogue, description and pacing","b":"201–210","g":"WR"},{"n":12,"t":"mc","s":"Which sentence would be the BEST ending for the story?","o":["I realized then that the bond between a falcon and its trainer is built on years of trust.","The desert can be dangerous at night because it becomes very dark and surprisingly cold.","Falcons have excellent eyesight and can see small animals from very high up in the sky.","My grandfather’s glove is made of thick brown leather that protects his hand."],"k":"A","sk":"Chooses an effective concluding sentence","b":"211–220","g":"WR"}]},{"passage":{"title":"Every Student Should Volunteer","genre":"draft","paras":["(1) Every middle school student should volunteer at least ten hours each year. (2) Volunteering teaches responsibility because people depend on volunteers to show up. (3) It also helps students discovering interests that could lead to future careers. (4) For example, my cousin volunteered at an animal shelter and now wants to become a veterinarian. (5) Some people argue that students are already too busy with schoolwork. (6) However, ten hours a year is less than one hour a month. (7) Volunteering helps communities and it helps students grow."],"intro":"Dalia wrote an argument essay. Read her draft and answer the questions."},"items":[{"n":13,"t":"mc","s":"Which sentence states Dalia’s claim?","o":["sentence 1","sentence 2","sentence 3","sentence 6"],"k":"A","sk":"States a clear claim or thesis","b":"181–190","g":"WR"},{"n":14,"t":"mc","s":"Where should a comma be added in sentence 7?","o":["after “Volunteering”","after “students”","after “communities”","after “helps”"],"k":"C","sk":"Uses a comma before a conjunction in a compound sentence","b":"191–200","g":"ME"},{"n":15,"t":"mc","s":"What is the purpose of sentence 4?","o":["to state the writer’s claim for the first time","to give an example that supports sentence 3","to introduce a counterclaim against the writer","to summarize all of the reasons in the essay"],"k":"B","sk":"Chooses relevant evidence to support a point","b":"191–200","g":"WR"},{"n":16,"t":"mc","s":"Which word should replace “discovering” in sentence 3?","o":["discovers","to discovering","discovered","discover"],"k":"D","sk":"Uses verbals: gerunds, participles and infinitives","b":"201–210","g":"GU"},{"n":17,"t":"mc","s":"How does sentence 6 respond to the counterclaim in sentence 5?","o":["It explains what an animal shelter does.","It gives a new reason to support volunteering.","It agrees that students are much too busy.","It shows that the time required is very small."],"k":"D","sk":"Acknowledges and answers an opposing claim","b":"201–210","g":"WR"},{"n":18,"t":"mc","s":"Which sentence would BEST replace sentence 7 as a conclusion?","o":["Animal shelters care for dogs and cats until they are able to find new homes and families.","By giving just a few hours, students can strengthen their communities and themselves.","Ten hours is the same as six hundred minutes, which is a lot of minutes.","Schoolwork includes homework, projects, tests and reading assignments too."],"k":"B","sk":"Chooses an effective concluding sentence","b":"211–220","g":"WR"}]},{"passage":null,"items":[{"n":19,"t":"mc","s":"Which transition BEST shows the relationship between the sentences?\n“The roads were icy. ___, the school opened two hours late.”","o":["As a result","Similarly","In contrast","For instance"],"k":"A","sk":"Chooses a transition that connects ideas","b":"191–200","g":"WR"},{"n":20,"t":"mc","s":"Which sentence is written in an objective tone for a report?","o":["Everyone will love the amazing new park, and I mean everyone!","The new park is absolutely the best place in the whole entire city.","The new park includes a playground, walking trails and a small lake.","The new park is way cooler than the boring old one on Main Street."],"k":"C","sk":"Keeps a consistent formal style and objective tone","b":"201–210","g":"WR"},{"n":21,"t":"mc","s":"A student wants to quote an expert in a report. Which sentence correctly gives credit?","o":["Coral reefs are the nurseries of the sea, and I thought of that interesting idea all by myself.","According to Dr. Huda Salem, a marine biologist, “Coral reefs are the nurseries of the sea.”","Somebody once said that coral reefs are the nurseries of the sea, I think.","“Coral reefs are the nurseries of the sea,” which is a very true thing to say."],"k":"B","sk":"Paraphrases or cites a source correctly","b":"211–220","g":"WR"}],"label":"Writing"},{"passage":null,"items":[{"n":22,"t":"mc","s":"Which pronoun correctly completes the sentence?\n“The tour guide showed Sami and ___ the old fort.”","o":["them","their","they","themselves"],"k":"A","sk":"Uses the correct pronoun case","b":"181–190","g":"GU"},{"n":23,"t":"mc","s":"Which sentence is written correctly?","o":["Myself and Hessa are going to the library.","Hessa and me are going to the library.","Me and Hessa are going to the library.","Hessa and I are going to the library."],"k":"D","sk":"Uses the correct pronoun case","b":"181–190","g":"GU"},{"n":24,"t":"mc","s":"Which of these is a fragment?","o":["The store was closed on Friday.","Since the store was closed, we went home.","Since the store was closed on Friday.","We went home because the store was closed."],"k":"C","sk":"Recognizes complete sentences, fragments and run-ons","b":"181–190","g":"GU"},{"n":25,"t":"mc","s":"Which sentence uses an intensive pronoun correctly?","o":["The students organized the charity sale theirselves.","The students themselves organized the charity sale.","The students and themselves organized the charity sale.","Themselves, the students organized the charity sale."],"k":"B","sk":"Uses reflexive and intensive pronouns","b":"191–200","g":"GU"},{"n":26,"t":"mc","s":"Which word correctly completes the sentence?\n“The list of supplies ___ on the board.”","o":["were","are","have been","is"],"k":"D","sk":"Makes subjects and verbs agree","b":"191–200","g":"GU"},{"n":27,"t":"mc","s":"Which word correctly completes the sentence?\n“The new rule will ___ every student in the school.”","o":["affect","affection","effects","effect"],"k":"A","sk":"Chooses between frequently confused words","b":"191–200","g":"GU"},{"n":28,"t":"mc","s":"Which sentence has an incorrect shift in pronoun person?","o":["When we arrived at the zoo, we could hear the lions roaring.","When I arrived at the zoo, I could hear the lions roaring.","When we arrived at the zoo, you could hear the lions roaring.","When they arrived at the zoo, they could hear the lions roaring."],"k":"C","sk":"Makes pronouns agree with their antecedents","b":"201–210","g":"GU"},{"n":29,"t":"mc","s":"Which sentence uses parallel structure?","o":["I like hiking, to swim and reading.","I like hiking, swimming and reading.","I like to hike, swimming and reading.","I like hiking, swimming and to read."],"k":"B","sk":"Uses parallel structure","b":"201–210","g":"GU"},{"n":30,"t":"mc","s":"Which words correctly complete the sentence?\n“Laila ___ the piano since she was six years old.”","o":["has played","plays since","have played","is playing"],"k":"A","sk":"Uses perfect verb tenses","b":"201–210","g":"GU"},{"n":31,"t":"mc","s":"Which sentence has a vague pronoun?","o":["Faris and Ali argued, and then Ali left the room.","After Faris argued with Ali, Faris left the room.","Faris argued with Ali and then left the room.","Faris and Ali argued, and then he left the room."],"k":"D","sk":"Corrects vague or unclear pronouns","b":"211–220","g":"GU"},{"n":32,"t":"mc","s":"Which word correctly completes the sentence?\n“The girl ___ I met at camp sent me a letter.”","o":["which","whose","whom","what"],"k":"C","sk":"Uses relative pronouns and relative adverbs","b":"211–220","g":"GU"}],"label":"Grammar and Usage"},{"passage":null,"items":[{"n":33,"t":"mc","s":"Which sentence uses a comma correctly?","o":["Well I think, we should wait a little longer.","Well I think we should wait, a little longer.","Well, I think we should wait a little longer.","Well I, think we should wait a little longer."],"k":"C","sk":"Uses a comma after an introductory word, phrase or clause","b":"181–190","g":"ME"},{"n":34,"t":"mc","s":"Which sentence uses commas correctly?","o":["The Nile the longest, river in Africa flows north.","The Nile, the longest river in Africa, flows north.","The Nile, the longest river in Africa flows north.","The Nile the longest river in Africa, flows north."],"k":"B","sk":"Uses commas, parentheses or dashes to set off extra information","b":"181–190","g":"ME"},{"n":35,"t":"mc","s":"Which sentence uses a comma correctly?","o":["The library was quiet, so I finished my essay.","The library was quiet so I finished, my essay.","The library, was quiet so I finished my essay.","The library was quiet so, I finished my essay."],"k":"A","sk":"Uses a comma before a conjunction in a compound sentence","b":"181–190","g":"ME"},{"n":36,"t":"mc","s":"Which sentence is capitalized correctly?","o":["My Aunt works for the Ministry of Education in Jeddah.","My aunt works for the Ministry of education in jeddah.","My aunt works for the ministry of education in Jeddah.","My aunt works for the Ministry of Education in Jeddah."],"k":"D","sk":"Capitalizes proper nouns, titles and sentence beginnings","b":"191–200","g":"ME"},{"n":37,"t":"mc","s":"Which sentence uses commas correctly?","o":["The bright colorful, kites filled the sky.","The, bright colorful kites filled the sky.","The bright, colorful kites filled the sky.","The bright, colorful, kites filled the sky."],"k":"C","sk":"Uses commas between coordinate adjectives","b":"191–200","g":"ME"},{"n":38,"t":"mc","s":"Which sentence is punctuated correctly?","o":["Watch out! “shouted the lifeguard.”","“Watch out,” shouted the lifeguard!","“Watch out!” Shouted the lifeguard.","“Watch out!” shouted the lifeguard."],"k":"D","sk":"Punctuates dialogue and quotations","b":"191–200","g":"ME"},{"n":39,"t":"mc","s":"Which word is spelled correctly?","o":["liberry","library","librery","libary"],"k":"B","sk":"Spells grade-level words correctly","b":"191–200","g":"ME"},{"n":40,"t":"mc","s":"Which sentence uses dashes correctly?","o":["The guest speaker—a famous astronaut—told us about space.","The guest speaker—a famous astronaut told us—about space.","The guest—speaker a famous astronaut—told us about space.","—The guest speaker a famous astronaut told us about space."],"k":"A","sk":"Uses commas, parentheses or dashes to set off extra information","b":"201–210","g":"ME"},{"n":41,"t":"mc","s":"Which sentence uses apostrophes correctly?","o":["The students’s projects were displayed in the hall.","The students projects’ were displayed in the hall.","The student’s projects were displayed in the halls’.","The students’ projects were displayed in the hall."],"k":"D","sk":"Uses apostrophes in contractions and possessives","b":"201–210","g":"ME"},{"n":42,"t":"mc","s":"Which title should be written in italics or underlined?","o":["the title of an article in a newspaper","the title of a song","the name of a newspaper","the title of a poem"],"k":"C","sk":"Capitalizes and punctuates titles of works","b":"201–210","g":"ME"},{"n":43,"t":"mc","s":"Which sentence is punctuated correctly?","o":["Hiking—not swimming—is my favorite summer activity.","Hiking—not swimming is my favorite—summer activity.","Hiking not—swimming—is my favorite summer activity.","Hiking—not swimming is—my favorite summer activity."],"k":"A","sk":"Uses hyphens and dashes correctly","b":"211–220","g":"ME"}],"label":"Capitalization, Punctuation and Spelling"}]},{"id":"D","note":"Full practice test · 43 questions · harder","sections":[{"passage":{"title":"How Desalination Works","genre":"draft","paras":["(1) Saudi Arabia has no permanent rivers. (2) To get enough fresh water, the country removes salt from seawater. (3) This process is called desalination. (4) In one common method called reverse osmosis, seawater is pushed through a special filter. (5) The filter has holes so tiny that salt cannot passes through. (6) Desalination plants use a lot of energy. (7) Scientists are studying how solar power could make desalination cheaper and cleaner."],"intro":"Maryam is writing a science report. Read her draft and answer the questions."},"items":[{"n":1,"t":"mc","s":"Which word in the draft is a domain-specific term that Maryam explains for her readers?","o":["rivers","desalination","cheaper","energy"],"k":"B","sk":"Chooses precise or vivid language","b":"191–200","g":"WR"},{"n":2,"t":"mc","s":"Which transition BEST begins sentence 6 to introduce a problem?","o":["For example,","Similarly,","Therefore,","However,"],"k":"D","sk":"Chooses a transition that connects ideas","b":"191–200","g":"WR"},{"n":3,"t":"mc","s":"Which word should replace “passes” in sentence 5?","o":["pass","passing","to pass","passed"],"k":"A","sk":"Uses modal auxiliaries","b":"191–200","g":"GU"},{"n":4,"t":"mc","s":"What is the correct way to write the beginning of sentence 4?","o":["In one common method, called reverse osmosis seawater","In one common method called reverse osmosis seawater","In one common method, called reverse osmosis, seawater","In one, common method called reverse osmosis, seawater"],"k":"C","sk":"Uses commas, parentheses or dashes to set off extra information","b":"201–210","g":"ME"},{"n":5,"t":"mc","s":"Which sentence would BEST follow sentence 1?","o":["Rivers around the world are home to many kinds of fish, birds and plants.","Some lakes in colder countries are frozen during the winter months.","The Red Sea is a popular place for swimming and diving in summer.","Most of the country also receives very little rain each year."],"k":"D","sk":"Adds a detail that supports the main idea","b":"201–210","g":"WR"},{"n":6,"t":"mc","s":"Which sentence would be the BEST conclusion for the report?","o":["As technology improves, desalination may provide fresh water to even more people.","Solar panels are often placed on the rooftops of houses to collect energy from sunlight.","Many people drink bottled water instead of tap water in hot countries.","Seawater tastes salty because it contains many dissolved minerals and salts."],"k":"A","sk":"Chooses an effective concluding sentence","b":"211–220","g":"WR"}]},{"passage":{"title":"The New Student","genre":"draft","paras":["(1) On the first day of school, a girl I had never seen sat alone at lunch. (2) She stared at her tray and didn’t touch her food. (3) My friends and I were laughing at a joke, but I kept glancing at her. (4) Finally, I picked up my tray and walked over. (5) “Is this seat taken” I asked. (6) She looked up, surprised, and shook her head. (7) By the end of lunch, Mira and me had discovered that we both loved drawing."],"intro":"Ruba is writing a story. Read her draft and answer the questions."},"items":[{"n":7,"t":"mc","s":"Which word in sentence 4 shows that the narrator had been thinking about this for a while?","o":["picked","Finally","walked","tray"],"k":"B","sk":"Chooses a transition that connects ideas","b":"181–190","g":"WR"},{"n":8,"t":"mc","s":"What is the correct way to write sentence 5?","o":["“Is this seat taken” I asked?","“Is this seat taken,” I asked?","“Is this seat taken?” I asked.","“Is this seat taken?” I asked?"],"k":"C","sk":"Punctuates dialogue and quotations","b":"191–200","g":"ME"},{"n":9,"t":"mc","s":"Which words should replace “Mira and me” in sentence 7?","o":["Mira and myself","Mira and mine","me and Mira","Mira and I"],"k":"D","sk":"Uses the correct pronoun case","b":"191–200","g":"GU"},{"n":10,"t":"mc","s":"What does sentence 2 suggest about the new girl?","o":["She dislikes the food at the school.","She is full because she ate a big breakfast.","She feels lonely or nervous.","She is angry with the narrator."],"k":"C","sk":"Uses narrative techniques: dialogue, description and pacing","b":"191–200","g":"WR"},{"n":11,"t":"mc","s":"Which sentence could be added after sentence 6 to develop the characters through dialogue?","o":["I sat down across from her and put my tray on the table.","“I’m Mira,” she said quietly. “I just moved here from Jeddah.”","The cafeteria was crowded and noisy, as it usually is at noon.","Lunch at our school lasts for about thirty minutes every day."],"k":"B","sk":"Uses narrative techniques: dialogue, description and pacing","b":"201–210","g":"WR"},{"n":12,"t":"mc","s":"Which sentence would be the BEST ending for the story?","o":["Sometimes, all it takes to make a friend is the courage to say hello.","Mira’s family moved to our city because her father got a new job.","The art room at our school has paint, clay, paper and colored pencils.","Lunch was rice and chicken that day, which is one of my favorite meals."],"k":"A","sk":"Chooses an effective concluding sentence","b":"201–210","g":"WR"}]},{"passage":{"title":"Should Schools Have a Four-Day Week?","genre":"draft","paras":["(1) Some schools have switched to a four-day school week, but our school should keep five days. (2) With only four days, each school day would have to be much longer. (3) Long days can leave younger students tired and unable to focus. (4) In addition, many parents work five days a week and would need to find childcare on the fifth day. (5) Supporters of the four day week say it saves money on buses and electricity. (6) However, studies show that the savings are often small, usually less than two percent of a school’s budget. (7) For these reasons, a five-day week are the better choice for our students."],"intro":"Saad wrote an argument essay. Read his draft and answer the questions."},"items":[{"n":13,"t":"mc","s":"Which sentence first states Saad’s claim?","o":["sentence 1","sentence 2","sentence 5","sentence 6"],"k":"A","sk":"States a clear claim or thesis","b":"181–190","g":"WR"},{"n":14,"t":"mc","s":"Which word should replace “are” in sentence 7?","o":["be","is","have been","were"],"k":"B","sk":"Makes subjects and verbs agree","b":"191–200","g":"GU"},{"n":15,"t":"mc","s":"Which sentence presents a counterclaim?","o":["sentence 3","sentence 4","sentence 5","sentence 6"],"k":"C","sk":"Acknowledges and answers an opposing claim","b":"191–200","g":"WR"},{"n":16,"t":"mc","s":"What is the correct way to write “four day week” in sentence 5?","o":["fourday week","four day-week","four-day-week","four-day week"],"k":"D","sk":"Uses hyphens and dashes correctly","b":"201–210","g":"ME"},{"n":17,"t":"mc","s":"Which revision of sentence 3 is MOST formal and precise?","o":["Long days are bad for kids because they get really tired and stuff like that.","Long days can make younger students really, really tired, you know what I mean?","Long school days can cause younger students to become fatigued and lose focus.","Long days can make the little kids super tired and totally zoned out by the afternoon."],"k":"C","sk":"Keeps a consistent formal style and objective tone","b":"201–210","g":"WR"},{"n":18,"t":"mc","s":"How does sentence 6 strengthen Saad’s argument?","o":["It introduces a new claim that disagrees with sentence 1.","It uses evidence to show that the opposing view is weak.","It explains how electricity is produced and delivered.","It tells a personal story about riding the school bus."],"k":"B","sk":"Acknowledges and answers an opposing claim","b":"211–220","g":"WR"}]},{"passage":null,"items":[{"n":19,"t":"mc","s":"Which sentence would BEST introduce an essay comparing two sports?","o":["Although soccer and basketball are both team sports, they test players in very different ways.","I like soccer, and I also like basketball, and I will write about both of them now.","Soccer is played with a ball, and the ball is round, and it is kicked by players.","Sports are activities that many people do, and there are lots of different sports to choose from."],"k":"A","sk":"Chooses an effective introduction","b":"201–210","g":"WR"},{"n":20,"t":"mc","s":"Which sentence would BEST support the claim “Learning to cook builds independence”?","o":["Cooking shows are popular on television and online in many countries.","Rice is one of the most common foods eaten around the world today.","Some kitchens have gas stoves, while other kitchens have electric stoves or ovens.","Students who can cook simple meals do not have to rely on others to feed them."],"k":"D","sk":"Chooses relevant evidence to support a point","b":"201–210","g":"WR"},{"n":21,"t":"mc","s":"Which revision removes the unnecessary words from this sentence?\n“In my opinion, I think that the library should be open longer hours.”","o":["I think that, in my opinion, the library should be open longer hours.","In my opinion, I think the library should be open longer hours.","The library should stay open for longer hours.","In my own personal opinion, the library should be open longer hours."],"k":"C","sk":"Revises to remove wordy or repeated language","b":"211–220","g":"WR"}],"label":"Writing"},{"passage":null,"items":[{"n":22,"t":"mc","s":"Which pronoun correctly completes the sentence?\n“Fatimah gave ___ a ride to the mall.”","o":["us","we","ourselves","our"],"k":"A","sk":"Uses the correct pronoun case","b":"181–190","g":"GU"},{"n":23,"t":"mc","s":"Which word correctly completes the sentence?\n“Of all the runners, Talal ran the ___.”","o":["more fast","fastest","most fastest","faster"],"k":"B","sk":"Uses adjectives and adverbs correctly, including comparisons","b":"181–190","g":"GU"},{"n":24,"t":"mc","s":"Which sentence is a complex sentence?","o":["The rain stopped; we played outside.","We played outside in the bright sunshine.","The rain stopped, and we played outside.","When the rain stopped, we played outside."],"k":"D","sk":"Forms simple, compound and complex sentences","b":"191–200","g":"GU"},{"n":25,"t":"mc","s":"Which word correctly completes the sentence?\n“The flowers in the garden ___ beautiful.”","o":["is","has been","are","was"],"k":"C","sk":"Makes subjects and verbs agree","b":"191–200","g":"GU"},{"n":26,"t":"mc","s":"Which sentence uses an intensive pronoun?","o":["The mayor herself opened the new park.","The new park was opened by the mayor.","The mayor opened the new park with her family.","She opened the new park on Saturday."],"k":"A","sk":"Uses reflexive and intensive pronouns","b":"191–200","g":"GU"},{"n":27,"t":"mc","s":"Which word correctly completes the sentence?\n“We visited every museum ___ the science museum.”","o":["accept","except","expect","excess"],"k":"B","sk":"Chooses between frequently confused words","b":"191–200","g":"GU"},{"n":28,"t":"mc","s":"Which sentence has an incorrect shift in pronoun person?","o":["If people want to learn an instrument, they must practice every day.","If you want to learn an instrument, you must practice every day.","If a person wants to learn an instrument, he or she must practice every day.","If a person wants to learn an instrument, we must practice every day."],"k":"D","sk":"Makes pronouns agree with their antecedents","b":"201–210","g":"GU"},{"n":29,"t":"mc","s":"Which is the BEST way to fix this comma splice?\n“The hike was long, we were exhausted.”","o":["The hike was long we were exhausted.","The hike was long, so we were exhausted.","The hike, was long we were exhausted.","The hike was long, we were, exhausted."],"k":"B","sk":"Recognizes complete sentences, fragments and run-ons","b":"201–210","g":"GU"},{"n":30,"t":"mc","s":"Which words correctly complete the sentence?\n“By next summer, my sister ___ to drive.”","o":["had learned","will had learned","will have learned","has learned"],"k":"C","sk":"Uses perfect verb tenses","b":"201–210","g":"GU"},{"n":31,"t":"mc","s":"Which sentence has a clear pronoun reference?","o":["When the glass hit the plate, the glass broke.","When the glass hit the plate, it broke into pieces.","It broke when the glass hit the plate.","The glass hit the plate, and it broke."],"k":"A","sk":"Corrects vague or unclear pronouns","b":"211–220","g":"GU"},{"n":32,"t":"mc","s":"Which word correctly completes the sentence?\n“The author ___ book won the prize will visit our school.”","o":["whom","which","who’s","whose"],"k":"D","sk":"Uses relative pronouns and relative adverbs","b":"211–220","g":"GU"}],"label":"Grammar and Usage"},{"passage":null,"items":[{"n":33,"t":"mc","s":"Which sentence uses a comma correctly?","o":["After, lunch we visited the zoo.","After lunch, we visited the zoo.","After lunch we visited, the zoo.","After lunch we, visited the zoo."],"k":"B","sk":"Uses a comma after an introductory word, phrase or clause","b":"181–190","g":"ME"},{"n":34,"t":"mc","s":"Which sentence is capitalized correctly?","o":["Our class is reading a Book about the Ottoman empire.","Our class is reading a book about the ottoman empire.","Our class is reading a book about the Ottoman Empire.","Our Class is reading a book about the Ottoman Empire."],"k":"C","sk":"Capitalizes proper nouns, titles and sentence beginnings","b":"181–190","g":"ME"},{"n":35,"t":"mc","s":"Which sentence uses commas correctly?","o":["Mr. Adel our science teacher, loves astronomy.","Mr. Adel, our science teacher loves astronomy.","Mr. Adel our, science teacher loves astronomy.","Mr. Adel, our science teacher, loves astronomy."],"k":"D","sk":"Uses commas, parentheses or dashes to set off extra information","b":"191–200","g":"ME"},{"n":36,"t":"mc","s":"Which sentence uses commas correctly?","o":["We walked along the narrow, winding path.","We walked, along the narrow winding path.","We walked along the, narrow winding path.","We walked along the narrow winding, path."],"k":"A","sk":"Uses commas between coordinate adjectives","b":"191–200","g":"ME"},{"n":37,"t":"mc","s":"Which sentence is punctuated correctly?","o":["Mom asked “Did you lock the door?”","Mom asked, “Did you lock the door”?","Mom asked, “did you lock the door?”","Mom asked, “Did you lock the door?”"],"k":"D","sk":"Punctuates dialogue and quotations","b":"191–200","g":"ME"},{"n":38,"t":"mc","s":"Which sentence uses apostrophes correctly?","o":["Your going to love you’re new room.","You’re going to love you’re new room.","You’re going to love your new room.","Your going to love your new room."],"k":"C","sk":"Uses apostrophes in contractions and possessives","b":"191–200","g":"ME"},{"n":39,"t":"mc","s":"Which word is spelled correctly?","o":["belive","believe","beleive","beleave"],"k":"B","sk":"Spells grade-level words correctly","b":"191–200","g":"ME"},{"n":40,"t":"mc","s":"Which sentence uses parentheses correctly?","o":["The test (which lasted two hours) was harder than I expected.","The test which (lasted two hours) was harder than I expected.","The test (which lasted two hours was harder) than I expected.","(The test) which lasted two hours was harder than I expected."],"k":"A","sk":"Uses commas, parentheses or dashes to set off extra information","b":"201–210","g":"ME"},{"n":41,"t":"mc","s":"Which sentence uses a dash correctly?","o":["I know exactly what—we need more time.","I—know exactly what we need more time.","I know exactly what we need—more time.","I know exactly—what we need more time."],"k":"C","sk":"Uses hyphens and dashes correctly","b":"201–210","g":"ME"},{"n":42,"t":"mc","s":"Which title should be written in quotation marks?","o":["the title of a song on an album","the title of a newspaper","the title of the album","the name of a television series"],"k":"A","sk":"Capitalizes and punctuates titles of works","b":"201–210","g":"ME"},{"n":43,"t":"mc","s":"Which word is spelled correctly?","o":["imediately","immediatley","immediatly","immediately"],"k":"D","sk":"Spells grade-level words correctly","b":"211–220","g":"ME"}],"label":"Capitalization, Punctuation and Spelling"}]},{"id":"E","note":"Final full practice test · 43 questions · hardest","sections":[{"passage":{"title":"The Invention of Paper","genre":"draft","paras":["(1) Before paper was invented, people wrote on clay tablets, animal skins and silk. (2) These materials were heavy, expensive or difficult to make. (3) Around the year 105, a Chinese official named Cai Lun improved a way to make paper from tree bark, old rags and plants. (4) For centuries, the Chinese kept their method a secret. (5) In the 700s, papermaking spread to Samarkand and then to Baghdad, where paper mills were built. (6) From there, the knowledge traveled to north africa and Europe. (7) Paper made books more cheaper, and more people could learn to read."],"intro":"Lulwa is writing a history report. Read her draft and answer the questions."},"items":[{"n":1,"t":"mc","s":"Which transition could BEST begin sentence 2 to show how it relates to sentence 1?","o":["In conclusion,","Unfortunately,","For example,","Similarly,"],"k":"B","sk":"Chooses a transition that connects ideas","b":"201–210","g":"WR"},{"n":2,"t":"mc","s":"What is the correct way to write the end of sentence 6?","o":["to North Africa and Europe.","to North africa and europe.","to north Africa and Europe.","to North Africa and europe."],"k":"A","sk":"Capitalizes proper nouns, titles and sentence beginnings","b":"201–210","g":"ME"},{"n":3,"t":"mc","s":"Which words should replace “more cheaper” in sentence 7?","o":["more cheapest","cheapest","cheaper","most cheap"],"k":"C","sk":"Uses adjectives and adverbs correctly, including comparisons","b":"201–210","g":"GU"},{"n":4,"t":"mc","s":"Lulwa wants to add a sentence that explains how Cai Lun’s paper was made. Where should it go?","o":["after sentence 1","after sentence 3","after sentence 5","after sentence 7"],"k":"B","sk":"Puts sentences or events in a logical order","b":"201–210","g":"WR"},{"n":5,"t":"mc","s":"Which revision of sentence 7 BEST explains the effect of paper?","o":["Paper made books cheaper, and many books are still printed on paper today.","Paper made books cheaper, and books are fun to read on long, rainy weekends at home.","Paper made books cheaper, and some of the longest books have hundreds and hundreds of pages.","Because paper made books cheaper, more people could afford them and learn to read."],"k":"D","sk":"Revises a sentence to make the meaning clearer","b":"211–220","g":"WR"},{"n":6,"t":"mc","s":"Which detail from another source would BEST support sentence 5?","o":["Baghdad is the capital city of Iraq, and the Tigris River flows through it.","Samarkand is famous for its beautiful blue-tiled mosques and its markets.","Records show that a paper mill was operating in Baghdad by the year 794.","Many types of paper today are made from recycled newspapers and boxes."],"k":"C","sk":"Chooses relevant evidence to support a point","b":"211–220","g":"WR"}]},{"passage":{"title":"The Final Match","genre":"draft","paras":["(1) The clock ticked loudly as I stared at the chessboard. (2) My opponent, a tall boy from Dammam, had just captured my queen. (3) My hands was sweating, and my heart pounded. (4) I remembered what my coach always said: “Never give up until the game is over.” (5) I studied the board and noticed that his king was unprotected. (6) Slowly, I moved my knight forward. (7) “Checkmate” I said quietly."],"intro":"Hassan wrote a story about a chess tournament. Read his draft and answer the questions."},"items":[{"n":7,"t":"mc","s":"Which word could replace “moved” in sentence 6 to show the narrator’s careful action?","o":["slid","threw","tossed","dropped"],"k":"A","sk":"Chooses precise or vivid language","b":"191–200","g":"WR"},{"n":8,"t":"mc","s":"Which word should replace “was” in sentence 3?","o":["be","is","has been","were"],"k":"D","sk":"Makes subjects and verbs agree","b":"201–210","g":"GU"},{"n":9,"t":"mc","s":"What is the correct way to write sentence 7?","o":["“Checkmate.” I said quietly.","“Checkmate” I said, quietly.","“Checkmate, I said quietly.”","“Checkmate,” I said quietly."],"k":"D","sk":"Punctuates dialogue and quotations","b":"201–210","g":"ME"},{"n":10,"t":"mc","s":"What is the effect of the details in sentences 1 and 3?","o":["They show how tense the narrator feels during the match.","They explain the rules for moving pieces in a game of chess.","They show that the narrator is bored and wants to leave early.","They describe where the chess tournament took place that day."],"k":"A","sk":"Uses narrative techniques: dialogue, description and pacing","b":"201–210","g":"WR"},{"n":11,"t":"mc","s":"Why does Hassan include the coach’s words in sentence 4?","o":["to describe the moment when the queen was captured","to show what gives the narrator the courage to keep going","to explain why the opponent traveled all the way from Dammam","to show that the coach is sitting and watching from the crowd"],"k":"B","sk":"Uses narrative techniques: dialogue, description and pacing","b":"211–220","g":"WR"},{"n":12,"t":"mc","s":"Which sentence would be the BEST ending for the story?","o":["A chessboard has sixty-four squares that are arranged in eight rows.","Dammam is a large and busy city on the eastern coast of Saudi Arabia, close to the Gulf.","As we shook hands, I knew I had learned something more valuable than winning: patience.","Chess was invented many centuries ago, and it was probably first played in ancient India."],"k":"C","sk":"Chooses an effective concluding sentence","b":"211–220","g":"WR"}]},{"passage":{"title":"Zoos: Helpful or Harmful?","genre":"draft","paras":["(1) Modern zoos play an important role in protecting wildlife. (2) Many zoos run breeding programs for endangered species. (3) The Arabian oryx, for example was saved from extinction partly through breeding programs in zoos. (4) Zoos also teach visitors about animals and their habitats. (5) Critics claim that animals in zoos are unhappy in small cages. (6) However, the best zoos now design large spaces that look like the animals’ natural homes. (7) If we want future generations to see these animals, we must supports good zoos."],"intro":"Shatha wrote an argument essay. Read her draft and answer the questions."},"items":[{"n":13,"t":"mc","s":"Which sentence BEST states Shatha’s claim?","o":["sentence 1","sentence 2","sentence 4","sentence 5"],"k":"A","sk":"States a clear claim or thesis","b":"191–200","g":"WR"},{"n":14,"t":"mc","s":"Where should a comma be added in sentence 3?","o":["after “partly”","after “saved”","after “extinction”","after “example”"],"k":"D","sk":"Uses commas, parentheses or dashes to set off extra information","b":"201–210","g":"ME"},{"n":15,"t":"mc","s":"Which word should replace “supports” in sentence 7?","o":["to support","supported","support","supporting"],"k":"C","sk":"Uses modal auxiliaries","b":"201–210","g":"GU"},{"n":16,"t":"mc","s":"Which evidence would BEST strengthen the response in sentence 6?","o":["Many families like to visit zoos together on weekends and during the long summer holidays.","A study of zoo animals found fewer signs of stress in large, natural-looking spaces.","Cages were common in zoos built more than one hundred years ago in Europe.","Some zoos sell toys, snacks and souvenirs in shops near the main entrance."],"k":"B","sk":"Acknowledges and answers an opposing claim","b":"211–220","g":"WR"},{"n":17,"t":"mc","s":"Which sentence would BEST follow sentence 4 to support it?","o":["Students who visit zoos often learn how human actions affect animal habitats.","Tickets to many zoos cost less for children than they do for adults.","Some animals, such as owls and bats, are much more active at night than during the day.","Zoos usually open early in the morning and close in the late afternoon."],"k":"A","sk":"Chooses relevant evidence to support a point","b":"211–220","g":"WR"},{"n":18,"t":"mc","s":"Which sentence could be added at the beginning to make a more engaging introduction?","o":["Zoos are places where animals live and where people go to look at the animals there.","Without zoos, some of the world’s most beautiful animals might exist only in photographs.","I went to a zoo once with my family, and we saw some animals that were very interesting.","This essay is going to be about zoos and whether zoos are good or bad for all of us."],"k":"B","sk":"Chooses an effective introduction","b":"211–220","g":"WR"}]},{"passage":null,"items":[{"n":19,"t":"mc","s":"Which sentence BEST fits a formal letter to a museum director?","o":["Hey, can I please talk to somebody who works at your museum for my school project?","Let me know if one of your people wants to talk, no big deal.","It would be super awesome if someone could chat with me sometime.","I would appreciate the opportunity to interview a member of your staff."],"k":"D","sk":"Keeps a consistent formal style and objective tone","b":"201–210","g":"WR"},{"n":20,"t":"mc","s":"Which question would be MOST useful for researching the effects of screen time on sleep?","o":["When was the first television invented, and who invented it?","How many different colors can most computer screens display?","How does using screens before bed affect how long children sleep?","What are the most popular video games and phone apps for children this year?"],"k":"C","sk":"Chooses a useful source or research question","b":"211–220","g":"WR"},{"n":21,"t":"mc","s":"Which sentence BEST combines the ideas using a transition that shows contrast?\n“Solar power is clean. It can be expensive to install.”","o":["Solar power is clean, so it can be expensive to install.","Because solar power is clean, it can be expensive to install.","Although solar power is clean, it can be expensive to install.","Solar power is clean, and it can also be expensive to install."],"k":"C","sk":"Chooses a transition that connects ideas","b":"211–220","g":"WR"}],"label":"Writing"},{"passage":null,"items":[{"n":22,"t":"mc","s":"Which pronoun correctly completes the sentence?\n“The judges awarded first prize to Rashed and ___.”","o":["her","herself","she","hers"],"k":"A","sk":"Uses the correct pronoun case","b":"191–200","g":"GU"},{"n":23,"t":"mc","s":"Which sentence uses pronouns correctly?","o":["Her and I finished the puzzle together.","She and me finished the puzzle together.","Her and me finished the puzzle together.","She and I finished the puzzle together."],"k":"D","sk":"Uses the correct pronoun case","b":"191–200","g":"GU"},{"n":24,"t":"mc","s":"Which sentence uses an intensive pronoun?","o":["He served us dessert after dinner.","The chef himself served us dessert.","Dessert was served by the chef.","The chef served us a large dessert."],"k":"B","sk":"Uses reflexive and intensive pronouns","b":"191–200","g":"GU"},{"n":25,"t":"mc","s":"Which sentence uses standard English?","o":["She don’t have no homework tonight.","She doesn’t have no homework tonight.","She doesn’t have any homework tonight.","She don’t have any homework tonight."],"k":"C","sk":"Chooses between frequently confused words","b":"201–210","g":"GU"},{"n":26,"t":"mc","s":"Which word correctly completes the sentence?\n“Each of the paintings ___ a different story.”","o":["are telling","tell","have told","tells"],"k":"D","sk":"Makes subjects and verbs agree","b":"201–210","g":"GU"},{"n":27,"t":"mc","s":"Which sentence has a pronoun that does NOT agree with its antecedent?","o":["The birds built its nest in the tree.","The birds built their nests in the tree.","The bird built its nest in the tree.","The bird and its mate built a nest."],"k":"A","sk":"Makes pronouns agree with their antecedents","b":"201–210","g":"GU"},{"n":28,"t":"mc","s":"Which is the BEST way to combine the sentences?\n“My uncle is a doctor. He works at a hospital in Abha.”","o":["My uncle is a doctor works at a hospital in Abha.","My uncle, a doctor, works at a hospital in Abha.","My uncle is a doctor, he works at a hospital in Abha.","My uncle, is a doctor, and works at a hospital in Abha."],"k":"B","sk":"Combines sentences correctly","b":"201–210","g":"GU"},{"n":29,"t":"mc","s":"Which sentence uses parallel structure?","o":["The coach told us to stretch, drinking water and to rest.","The coach told us stretching, to drink water and rest.","The coach told us to stretch, to drink water and to rest.","The coach told us to stretch, drink water and resting."],"k":"C","sk":"Uses parallel structure","b":"211–220","g":"GU"},{"n":30,"t":"mc","s":"Which sentence has a vague pronoun?","o":["According to the news, rain will fall all week.","The weather report says that it will rain all week.","Forecasters predict rain all week.","They say that it will rain all week."],"k":"D","sk":"Corrects vague or unclear pronouns","b":"211–220","g":"GU"},{"n":31,"t":"mc","s":"Which words correctly complete the sentence?\n“If she ___ about the test, she would have studied.”","o":["had known","knew","would know","has known"],"k":"A","sk":"Uses perfect verb tenses","b":"211–220","g":"GU"},{"n":32,"t":"mc","s":"Which sentence uses “whom” correctly?","o":["Whom will win the race?","To whom should I give this letter?","Whom is knocking so loudly at the front door?","Whom wants to play outside?"],"k":"B","sk":"Uses relative pronouns and relative adverbs","b":"211–220","g":"GU"}],"label":"Grammar and Usage"},{"passage":null,"items":[{"n":33,"t":"mc","s":"Which sentence uses a comma correctly?","o":["No, I have not seen that movie yet.","No I have, not seen that movie yet.","No I have not seen, that movie yet.","No I, have not seen that movie yet."],"k":"A","sk":"Uses a comma after an introductory word, phrase or clause","b":"191–200","g":"ME"},{"n":34,"t":"mc","s":"Which sentence is capitalized correctly?","o":["We studied the battle of Badr in History class.","We studied the Battle of Badr in history class.","We studied the Battle of badr in history class.","we studied the Battle of Badr in history class."],"k":"B","sk":"Capitalizes proper nouns, titles and sentence beginnings","b":"191–200","g":"ME"},{"n":35,"t":"mc","s":"Which sentence uses commas correctly?","o":["The, old crumbling wall needed repairs.","The old crumbling, wall needed repairs.","The old, crumbling, wall needed repairs.","The old, crumbling wall needed repairs."],"k":"D","sk":"Uses commas between coordinate adjectives","b":"201–210","g":"ME"},{"n":36,"t":"mc","s":"Which sentence uses parentheses correctly?","o":["(Mount Everest) the tallest mountain on Earth is in Asia.","Mount Everest (the tallest mountain on Earth is in Asia).","Mount Everest (the tallest mountain on Earth) is in Asia.","Mount Everest the tallest (mountain on Earth) is in Asia."],"k":"C","sk":"Uses commas, parentheses or dashes to set off extra information","b":"201–210","g":"ME"},{"n":37,"t":"mc","s":"Which sentence uses commas correctly?","o":["My best friend, who lives next door, plays the oud.","My best friend, who lives next door plays the oud.","My best friend who, lives next door plays the oud.","My best friend who lives next door, plays the oud."],"k":"A","sk":"Uses commas, parentheses or dashes to set off extra information","b":"201–210","g":"ME"},{"n":38,"t":"mc","s":"Which sentence uses apostrophes correctly?","o":["The two cat’s bowls were empty, so we filled them.","The two cats bowls’ were empty, so we filled them.","The two cats’s bowls were empty, so we filled them.","The two cats’ bowls were empty, so we filled them."],"k":"D","sk":"Uses apostrophes in contractions and possessives","b":"201–210","g":"ME"},{"n":39,"t":"mc","s":"Which sentence is punctuated correctly?","o":["“Please sit down,” said the teacher “and open your books.”","“Please sit down,” said the teacher, “and open your books.”","“Please sit down,” said the teacher, “And open your books.”","“Please sit down” said the teacher, “and open your books.”"],"k":"B","sk":"Punctuates dialogue and quotations","b":"211–220","g":"ME"},{"n":40,"t":"mc","s":"Which sentence uses a dash correctly?","o":["We—packed everything we needed tents, food and water.","We packed—everything we needed tents, food and water.","We packed everything we needed—tents, food and water.","We packed everything—we needed tents, food and water."],"k":"C","sk":"Uses hyphens and dashes correctly","b":"211–220","g":"ME"},{"n":41,"t":"mc","s":"Which sentence is written correctly?","o":["My favorite chapter is called The Hidden “Door.”","My favorite chapter is called “the hidden door.”","My favorite chapter is called “The Hidden Door.”","My favorite chapter is called “The Hidden door”."],"k":"C","sk":"Capitalizes and punctuates titles of works","b":"211–220","g":"ME"},{"n":42,"t":"mc","s":"Which word is spelled correctly?","o":["embarass","embarrass","embarras","imbarrass"],"k":"B","sk":"Spells grade-level words correctly","b":"211–220","g":"ME"},{"n":43,"t":"mc","s":"Which word is spelled correctly?","o":["accommodate","acommodate","acomodate","accomodate"],"k":"A","sk":"Spells grade-level words correctly","b":"221–230","g":"ME"}],"label":"Capitalization, Punctuation and Spelling"}]}]};
